#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum ShaderSamplerMode {
    LinearWrap,
    LinearClamp,
    PointClamp,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum ShaderSamplerResourceType {
    Texture2D,
    Cube,
    Shadow,
}

#[derive(Clone, Copy, Debug)]
struct ShaderSamplerExpectation {
    name: &'static str,
    index: u32,
    mode: ShaderSamplerMode,
    resource_type: ShaderSamplerResourceType,
}

