fn load_default_map_meta(path: &Path) -> Result<DefaultMapMeta> {
    let text = strip_comments(&read_latin1(path)?);
    let mut file_references = BTreeMap::new();
    for key in [
        "definitions",
        "provinces",
        "positions",
        "terrain",
        "rivers",
        "heightmap",
        "tree_definition",
        "continent",
        "adjacency_rules",
        "adjacencies",
        "ambient_object",
        "seasons",
    ] {
        if let Some(value) = parse_quoted_value(&text, key) {
            file_references.insert(key.to_string(), value);
        }
    }
    let tree_indices = extract_block_after(&text, "tree", 0)
        .map(|(inner, _)| parse_u32s(&inner))
        .unwrap_or_default();
    Ok(DefaultMapMeta {
        file_references,
        tree_indices,
    })
}

fn load_city_source_meta(path: &Path) -> Result<CitySourceMeta> {
    let text = strip_comments(&read_latin1(path)?);
    let mut city_groups = Vec::new();
    let mut search = 0usize;
    while let Some((inner, next)) = extract_block_after(&text, "city_group", search) {
        let mut buildings = Vec::new();
        let mut building_search = 0usize;
        while let Some((building_inner, building_next)) =
            extract_block_after(&inner, "building", building_search)
        {
            let meshes = extract_block_after(&building_inner, "mesh", 0)
                .map(|(mesh_inner, _)| parse_quoted_items(&mesh_inner))
                .unwrap_or_default();
            buildings.push(CityBuildingMeta {
                distance: parse_u32_value(&building_inner, "distance"),
                meshes,
            });
            building_search = building_next;
        }
        city_groups.push(CityGroupMeta {
            color_index: parse_u32_value(&inner, "color_index"),
            density: parse_f32_value(&inner, "density"),
            buildings,
        });
        search = next;
    }
    Ok(CitySourceMeta {
        types_source: parse_quoted_value(&text, "types_source"),
        pixel_step_x: parse_u32_value(&text, "pixel_step_x"),
        pixel_step_y: parse_u32_value(&text, "pixel_step_y"),
        city_groups,
    })
}

fn parse_quoted_items(text: &str) -> Vec<String> {
    let mut items = Vec::new();
    let mut rest = text;
    while let Some(start) = rest.find('"') {
        let after_start = &rest[start + 1..];
        let Some(end) = after_start.find('"') else {
            break;
        };
        items.push(after_start[..end].to_string());
        rest = &after_start[end + 1..];
    }
    items
}

fn indexed_map_meta(image: &IndexImage) -> IndexedMapMeta {
    let index_counts = indexed_counts(&image.pixels);
    let nonzero_pixels = image.pixels.iter().filter(|index| **index != 0).count();
    IndexedMapMeta {
        width: image.width,
        height: image.height,
        distinct_indices: index_counts.len(),
        nonzero_pixels,
        index_counts,
    }
}

fn indexed_counts(pixels: &[u8]) -> BTreeMap<u8, usize> {
    let mut index_counts = BTreeMap::new();
    for index in pixels {
        *index_counts.entry(*index).or_insert(0) += 1;
    }
    index_counts
}

fn load_season_source_meta(path: &Path) -> Result<SeasonSourceMeta> {
    let text = strip_comments(&read_latin1(path)?);
    let mut blocks = Vec::new();
    for name in ["winter", "spring", "summer", "autumn"] {
        if let Some((inner, _)) = extract_block_after(&text, name, 0) {
            blocks.push(SeasonBlockMeta {
                name: name.to_string(),
                start_date: parse_token_value(&inner, "start_date"),
                end_date: parse_token_value(&inner, "end_date"),
            });
        }
    }
    Ok(SeasonSourceMeta { blocks })
}

#[derive(Clone, Copy)]
enum Delimiter {
    Semicolon,
    Whitespace,
}

fn delimited_source_meta(
    path: &Path,
    delimiter: Delimiter,
    category_column: Option<usize>,
) -> Result<TabularSourceMeta> {
    let text = strip_comments(&read_latin1(path)?);
    let mut rows = 0usize;
    let mut malformed_rows = 0usize;
    let mut field_counts = BTreeMap::new();
    let mut category_counts = BTreeMap::new();
    for raw in text.lines() {
        let line = raw.trim();
        if line.is_empty() {
            continue;
        }
        let fields = match delimiter {
            Delimiter::Semicolon => line
                .split(';')
                .map(str::trim)
                .filter(|field| !field.is_empty())
                .collect::<Vec<_>>(),
            Delimiter::Whitespace => line.split_whitespace().collect::<Vec<_>>(),
        };
        if fields.is_empty() {
            malformed_rows += 1;
            continue;
        }
        rows += 1;
        *field_counts.entry(fields.len()).or_insert(0) += 1;
        if let Some(column) = category_column {
            if let Some(value) = fields.get(column) {
                *category_counts.entry((*value).to_string()).or_insert(0) += 1;
            } else {
                malformed_rows += 1;
            }
        }
    }
    Ok(TabularSourceMeta {
        rows,
        malformed_rows,
        field_counts,
        category_column,
        category_counts,
    })
}

fn load_ambient_source_meta(path: &Path) -> Result<AmbientSourceMeta> {
    let text = strip_comments(&read_latin1(path)?);
    let mut type_blocks = 0usize;
    let mut object_blocks = 0usize;
    let mut type_counts = BTreeMap::new();
    let mut object_name_counts = BTreeMap::new();
    let mut search = 0usize;
    while let Some((inner, next)) = extract_block_after(&text, "type", search) {
        type_blocks += 1;
        if let Some(type_name) = parse_quoted_value(&inner, "type") {
            *type_counts.entry(type_name).or_insert(0) += 1;
        }
        let mut object_search = 0usize;
        while let Some((object_inner, object_next)) =
            extract_block_after(&inner, "object", object_search)
        {
            object_blocks += 1;
            if let Some(name) = parse_quoted_value(&object_inner, "name") {
                *object_name_counts.entry(name).or_insert(0) += 1;
            }
            object_search = object_next;
        }
        search = next;
    }
    Ok(AmbientSourceMeta {
        type_blocks,
        object_blocks,
        type_counts,
        object_name_counts,
    })
}

fn load_common_building_rules(
    paths: &[(String, PathBuf)],
) -> Result<BTreeMap<String, CommonBuildingRuleMeta>> {
    let mut rules = BTreeMap::new();
    for (source, path) in paths {
        let text = strip_comments(&read_latin1(path)?);
        let Some((inner, _)) = extract_block_after(&text, "buildings", 0) else {
            continue;
        };
        for (name, block) in top_level_assignment_blocks(&inner) {
            let level_cap = extract_block_after(&block, "level_cap", 0).map(|(inner, _)| inner);
            let tags = extract_block_after(&block, "tags", 0)
                .map(|(inner, _)| parse_word_items(&inner))
                .unwrap_or_default();
            let key = if rules.contains_key(&name) {
                format!("{source}:{name}")
            } else {
                name
            };
            rules.insert(
                key,
                CommonBuildingRuleMeta {
                    source: source.clone(),
                    show_on_map: parse_u32_value(&block, "show_on_map"),
                    icon_frame: parse_u32_value(&block, "icon_frame"),
                    value: parse_u32_value(&block, "value"),
                    spawn_point: parse_word_value(&block, "spawn_point"),
                    province_max: level_cap
                        .as_deref()
                        .and_then(|inner| parse_u32_value(inner, "province_max")),
                    state_max: level_cap
                        .as_deref()
                        .and_then(|inner| parse_u32_value(inner, "state_max")),
                    centered: parse_bool_value(&block, "centered"),
                    always_shown: parse_bool_value(&block, "always_shown"),
                    only_display_if_exists: parse_bool_value(&block, "only_display_if_exists"),
                    tags,
                },
            );
        }
    }
    Ok(rules)
}

fn top_level_assignment_blocks(text: &str) -> Vec<(String, String)> {
    let bytes = text.as_bytes();
    let mut out = Vec::new();
    let mut i = 0usize;
    while i < bytes.len() {
        while i < bytes.len() && bytes[i].is_ascii_whitespace() {
            i += 1;
        }
        let key_start = i;
        while i < bytes.len() && is_word_byte(bytes[i]) {
            i += 1;
        }
        if key_start == i {
            i = i.saturating_add(1);
            continue;
        }
        let key = &text[key_start..i];
        while i < bytes.len() && bytes[i].is_ascii_whitespace() {
            i += 1;
        }
        if i >= bytes.len() || bytes[i] != b'=' {
            continue;
        }
        i += 1;
        while i < bytes.len() && bytes[i].is_ascii_whitespace() {
            i += 1;
        }
        if i >= bytes.len() || bytes[i] != b'{' {
            continue;
        }
        if let Some(block) = extract_brace_at(text, i) {
            let next = i + block.len() + 2;
            out.push((key.to_string(), block));
            i = next;
        } else {
            break;
        }
    }
    out
}

fn parse_bool_value(text: &str, key: &str) -> Option<bool> {
    parse_word_value(text, key).and_then(|value| match value.as_str() {
        "yes" => Some(true),
        "no" => Some(false),
        _ => None,
    })
}

fn parse_word_items(text: &str) -> Vec<String> {
    let mut out = Vec::new();
    let mut current = String::new();
    for ch in text.chars() {
        if ch.is_ascii_alphanumeric() || ch == '_' {
            current.push(ch);
        } else if !current.is_empty() {
            out.push(std::mem::take(&mut current));
        }
    }
    if !current.is_empty() {
        out.push(current);
    }
    out
}

fn load_text_source_catalogs<'a>(
    paths: impl Iterator<Item = (&'a str, &'a PathBuf)>,
) -> Result<BTreeMap<String, TextSourceCatalog>> {
    let mut catalogs = BTreeMap::new();
    for (source, path) in paths {
        catalogs.insert(source.to_string(), load_text_source_catalog(path)?);
    }
    Ok(catalogs)
}

fn load_text_source_catalog(path: &Path) -> Result<TextSourceCatalog> {
    let text = strip_comments(&read_latin1(path)?);
    Ok(TextSourceCatalog {
        bytes: fs::metadata(path)?.len(),
        lines: text.lines().filter(|line| !line.trim().is_empty()).count(),
        key_counts: assignment_key_counts(&text),
        quoted_values: quoted_value_catalog(&text),
    })
}

fn assignment_key_counts(text: &str) -> BTreeMap<String, usize> {
    let bytes = text.as_bytes();
    let mut counts = BTreeMap::new();
    let mut i = 0usize;
    while i < bytes.len() {
        let start = i;
        while i < bytes.len() && is_word_byte(bytes[i]) {
            i += 1;
        }
        if start != i {
            let key = &text[start..i];
            let mut j = i;
            while j < bytes.len() && bytes[j].is_ascii_whitespace() {
                j += 1;
            }
            if j < bytes.len() && bytes[j] == b'=' {
                *counts.entry(key.to_ascii_lowercase()).or_insert(0) += 1;
            }
        }
        i = i.saturating_add(1);
    }
    counts
}

fn quoted_value_catalog(text: &str) -> BTreeMap<String, Vec<String>> {
    let mut collected: BTreeMap<String, BTreeSet<String>> = BTreeMap::new();
    for (key, canonical) in [
        ("name", "name"),
        ("file", "file"),
        ("mesh", "mesh"),
        ("texturefile", "texturefile"),
        ("textureFile", "texturefile"),
        ("shader", "shader"),
    ] {
        let mut search = 0usize;
        while let Some(idx) = find_assignment(text, key, search) {
            let value = &text[idx..];
            if let Some(first) = value.find('"') {
                let rest = &value[first + 1..];
                if let Some(end) = rest.find('"') {
                    collected
                        .entry(canonical.to_string())
                        .or_default()
                        .insert(rest[..end].to_string());
                    search = idx + first + end + 2;
                    continue;
                }
            }
            search = idx.saturating_add(1);
        }
    }
    collected
        .into_iter()
        .map(|(key, values)| (key, values.into_iter().collect()))
        .collect()
}

fn load_country_tag_files(tags_dir: &Path) -> Result<BTreeMap<String, String>> {
    let mut out = BTreeMap::new();
    if !tags_dir.is_dir() {
        return Ok(out);
    }
    for entry in fs::read_dir(tags_dir)? {
        let path = entry?.path();
        if path.extension().and_then(|s| s.to_str()) != Some("txt") {
            continue;
        }
        let text = strip_comments(&read_latin1(&path)?);
        for line in text.lines() {
            let Some((left, right)) = line.split_once('=') else {
                continue;
            };
            let tag = left.trim();
            if !is_tag(tag) {
                continue;
            }
            let rel = right.trim().trim_matches('"').trim().to_string();
            if !rel.is_empty() {
                out.entry(tag.to_string()).or_insert(rel);
            }
        }
    }
    Ok(out)
}

fn is_tag(value: &str) -> bool {
    (2..=3).contains(&value.len())
        && value
            .bytes()
            .all(|b| b.is_ascii_uppercase() || b.is_ascii_digit())
}

fn load_country_file_color(path: &Path) -> Result<Option<[u8; 3]>> {
    if !path.is_file() {
        return Ok(None);
    }
    let text = strip_comments(&read_latin1(path)?);
    Ok(parse_color_assignment(&text, "color"))
}

fn load_colors_txt_overrides(path: &Path) -> Result<BTreeMap<String, [u8; 3]>> {
    let mut out = BTreeMap::new();
    if !path.is_file() {
        return Ok(out);
    }
    let text = strip_comments(&read_latin1(path)?);
    let bytes = text.as_bytes();
    let mut i = 0usize;
    while i < bytes.len() {
        while i < bytes.len() && bytes[i].is_ascii_whitespace() {
            i += 1;
        }
        let start = i;
        while i < bytes.len() && (bytes[i].is_ascii_uppercase() || bytes[i].is_ascii_digit()) {
            i += 1;
        }
        let tag = &text[start..i];
        if is_tag(tag) {
            let mut j = i;
            while j < bytes.len() && bytes[j].is_ascii_whitespace() {
                j += 1;
            }
            if j < bytes.len() && bytes[j] == b'=' {
                j += 1;
                while j < bytes.len() && bytes[j].is_ascii_whitespace() {
                    j += 1;
                }
                if j < bytes.len() && bytes[j] == b'{' {
                    let inner = extract_brace_at(&text, j).unwrap_or_default();
                    if let Some(color) = parse_color_assignment(&inner, "color") {
                        out.insert(tag.to_string(), color);
                    }
                    i = j + inner.len() + 2;
                    continue;
                }
            }
        }
        i = i.saturating_add(1);
    }
    Ok(out)
}

fn extract_brace_at(text: &str, brace: usize) -> Option<String> {
    let bytes = text.as_bytes();
    if bytes.get(brace) != Some(&b'{') {
        return None;
    }
    let mut depth = 0i32;
    let inner_start = brace + 1;
    for i in brace..bytes.len() {
        match bytes[i] {
            b'{' => depth += 1,
            b'}' => {
                depth -= 1;
                if depth == 0 {
                    return Some(text[inner_start..i].to_string());
                }
            }
            _ => {}
        }
    }
    None
}

fn parse_color_assignment(text: &str, key: &str) -> Option<[u8; 3]> {
    let idx = find_assignment(text, key, 0)?;
    let rest = &text[idx..];
    let brace = rest.find('{')?;
    let kind = rest[..brace].trim().to_ascii_lowercase();
    let inner = extract_brace_at(rest, brace)?;
    let nums = inner
        .split_whitespace()
        .filter_map(|part| part.parse::<f32>().ok())
        .collect::<Vec<_>>();
    if nums.len() < 3 {
        return None;
    }
    if kind == "hsv" && nums[0] <= 1.0 {
        Some(hsv_to_rgb(
            nums[0],
            nums[1].clamp(0.0, 1.0),
            nums[2].clamp(0.0, 1.0),
        ))
    } else {
        Some([
            nums[0].round().clamp(0.0, 255.0) as u8,
            nums[1].round().clamp(0.0, 255.0) as u8,
            nums[2].round().clamp(0.0, 255.0) as u8,
        ])
    }
}

fn hsv_to_rgb(h: f32, s: f32, v: f32) -> [u8; 3] {
    let h = (h.fract() * 6.0).max(0.0);
    let i = h.floor() as i32;
    let f = h - i as f32;
    let p = v * (1.0 - s);
    let q = v * (1.0 - f * s);
    let t = v * (1.0 - (1.0 - f) * s);
    let (r, g, b) = match i.rem_euclid(6) {
        0 => (v, t, p),
        1 => (q, v, p),
        2 => (p, v, t),
        3 => (p, q, v),
        4 => (t, p, v),
        _ => (v, p, q),
    };
    [
        (r * 255.0).round().clamp(0.0, 255.0) as u8,
        (g * 255.0).round().clamp(0.0, 255.0) as u8,
        (b * 255.0).round().clamp(0.0, 255.0) as u8,
    ]
}

fn make_map_visual(
    province_ids: &[u32],
    definitions: &BTreeMap<u32, ProvinceDefinition>,
    colormap: &RgbxImage,
    water: &RgbxImage,
    terrain_atlas: &RgbxImage,
    _underwater: &RgbxImage,
    _waterspec: &RgbxImage,
    _river_diffuse: &RgbxImage,
    _border_country: &RgbxImage,
    _border_state: &RgbxImage,
    _border_sea: &RgbxImage,
    terrain_indices: &IndexImage,
    terrain_texture_map: &BTreeMap<u8, u8>,
    heightmap: &IndexImage,
    _rivers: &IndexImage,
    _province_to_state: &BTreeMap<u32, u32>,
    _state_owners: &BTreeMap<u32, String>,
) -> Vec<u32> {
    let width = heightmap.width;
    let height = heightmap.height;
    let mut out = vec![0u32; width * height];

    for y in 0..height {
        for x in 0..width {
            let idx = y * width + x;
            let province = province_ids[idx];
            let is_water = definitions
                .get(&province)
                .map(|d| d.province_type == "sea" || d.province_type == "lake")
                .unwrap_or(true);
            let base = if is_water {
                sample_scaled(water, x, y, width, height)
            } else {
                sample_scaled(colormap, x, y, width, height)
            };
            out[idx] = if is_water {
                compose_water(base)
            } else {
                let terrain_index = terrain_indices.pixels[idx];
                let texture_id = terrain_texture_map
                    .get(&terrain_index)
                    .copied()
                    .unwrap_or(255);
                apply_terrain_texture(base, terrain_atlas, texture_id, x, y, width, height)
            };
        }
    }

    out
}

fn rgb_u32(rgb: [u8; 3]) -> u32 {
    (u32::from(rgb[0]) << 16) | (u32::from(rgb[1]) << 8) | u32::from(rgb[2])
}

fn rgb_tuple(color: u32) -> (u8, u8, u8) {
    (
        ((color >> 16) & 0xFF) as u8,
        ((color >> 8) & 0xFF) as u8,
        (color & 0xFF) as u8,
    )
}

fn sample_scaled(image: &RgbxImage, x: usize, y: usize, target_w: usize, target_h: usize) -> u32 {
    let sx = (x as f32 + 0.5) * image.width as f32 / target_w as f32 - 0.5;
    let sy = (y as f32 + 0.5) * image.height as f32 / target_h as f32 - 0.5;
    sample_xy_clamp_linear(image, sx, sy)
}

fn apply_terrain_texture(
    colormap: u32,
    atlas: &RgbxImage,
    texture_id: u8,
    x: usize,
    y: usize,
    map_w: usize,
    map_h: usize,
) -> u32 {
    if texture_id == 255 {
        return colormap;
    }
    let tile = usize::from(texture_id).min(MAP_NUM_TILES * MAP_NUM_TILES - 1);
    let index_u = (tile % MAP_NUM_TILES) as f32;
    let index_v = (tile / MAP_NUM_TILES) as f32;
    let uv2_x = (x as f32 + 0.5) / map_w as f32;
    let uv2_y = 1.0 - (y as f32 + 0.5) / map_h as f32;
    let mut tile_repeat_x = uv2_x * TERRAIN_TILE_FREQ;
    let tile_repeat_y = uv2_y * TERRAIN_TILE_FREQ;
    tile_repeat_x *= map_w as f32 / map_h as f32;
    let lod = 0.0f32;
    let mip_texels = 2.0f32.powf(ATLAS_TEXEL_POW2_EXPONENT - lod);
    let terrain = sample_terrain(
        atlas,
        index_u,
        index_v,
        tile_repeat_x,
        tile_repeat_y,
        mip_texels,
    );
    get_overlay(terrain, colormap, COLORMAP_OVERLAY_STRENGTH)
}

fn sample_terrain(
    atlas: &RgbxImage,
    index_u: f32,
    index_v: f32,
    tile_repeat_x: f32,
    tile_repeat_y: f32,
    mip_texels: f32,
) -> u32 {
    let (u, v) = terrain_sample_uv(index_u, index_v, tile_repeat_x, tile_repeat_y, mip_texels);
    sample_uv_wrap_linear(atlas, u, v)
}

fn sample_terrain_lod(
    atlas: &RgbaMipChain,
    index_u: f32,
    index_v: f32,
    tile_repeat_x: f32,
    tile_repeat_y: f32,
    mip_texels: f32,
    lod: f32,
) -> SampledLinearRgba {
    let (u, v) = terrain_sample_uv(index_u, index_v, tile_repeat_x, tile_repeat_y, mip_texels);
    sample_uv_wrap_linear_lod_linear_rgba(atlas, u, v, lod)
}

fn terrain_sample_uv(
    index_u: f32,
    index_v: f32,
    tile_repeat_x: f32,
    tile_repeat_y: f32,
    mip_texels: f32,
) -> (f32, f32) {
    let texels_per_tile = mip_texels / MAP_NUM_TILES as f32;
    let tile_scale = (texels_per_tile - 1.0) / texels_per_tile;
    let u =
        ((index_u + tile_repeat_x.fract() * tile_scale) / MAP_NUM_TILES as f32) + 0.5 / mip_texels;
    let v =
        ((index_v + tile_repeat_y.fract() * tile_scale) / MAP_NUM_TILES as f32) + 0.5 / mip_texels;
    (u, v)
}

fn sample_uv_wrap_linear(image: &RgbxImage, u: f32, v: f32) -> u32 {
    let x = u.rem_euclid(1.0) * image.width as f32 - 0.5;
    let y = v.rem_euclid(1.0) * image.height as f32 - 0.5;
    sample_xy_wrap_linear(image, x, y)
}

#[cfg(test)]
fn sample_uv_wrap_linear_lod_rgba(chain: &RgbaMipChain, u: f32, v: f32, lod: f32) -> SampledRgba {
    let max_level = chain.levels.len().saturating_sub(1);
    let lod = lod.clamp(0.0, max_level as f32);
    let low = lod.floor() as usize;
    let high = lod.ceil() as usize;
    let low_color = sample_uv_wrap_linear_rgba(&chain.levels[low], u, v);
    if low == high {
        return low_color;
    }
    let high_color = sample_uv_wrap_linear_rgba(&chain.levels[high], u, v);
    mix_sampled_rgba(low_color, high_color, lod - low as f32)
}

fn sample_uv_wrap_linear_lod_linear_rgba(
    chain: &RgbaMipChain,
    u: f32,
    v: f32,
    lod: f32,
) -> SampledLinearRgba {
    let max_level = chain.levels.len().saturating_sub(1);
    let lod = lod.clamp(0.0, max_level as f32);
    let low = lod.floor() as usize;
    let high = lod.ceil() as usize;
    let low_color = sample_uv_wrap_linear_linear_rgba(&chain.levels[low], chain.color_space, u, v);
    if low == high {
        return low_color;
    }
    let high_color =
        sample_uv_wrap_linear_linear_rgba(&chain.levels[high], chain.color_space, u, v);
    mix_sampled_linear_rgba(low_color, high_color, lod - low as f32)
}

fn sample_uv_clamp_linear_lod_linear_rgba(
    chain: &RgbaMipChain,
    u: f32,
    v: f32,
    lod: f32,
) -> SampledLinearRgba {
    let max_level = chain.levels.len().saturating_sub(1);
    let lod = lod.clamp(0.0, max_level as f32);
    let low = lod.floor() as usize;
    let high = lod.ceil() as usize;
    let low_color = sample_uv_clamp_linear_linear_rgba(&chain.levels[low], chain.color_space, u, v);
    if low == high {
        return low_color;
    }
    let high_color =
        sample_uv_clamp_linear_linear_rgba(&chain.levels[high], chain.color_space, u, v);
    mix_sampled_linear_rgba(low_color, high_color, lod - low as f32)
}

fn sample_uv_wrap_linear_rgba(image: &RgbaImage, u: f32, v: f32) -> SampledRgba {
    let x = u.rem_euclid(1.0) * image.width as f32 - 0.5;
    let y = v.rem_euclid(1.0) * image.height as f32 - 0.5;
    sample_xy_wrap_linear_rgba(image, x, y)
}

fn sample_uv_wrap_linear_linear_rgba(
    image: &RgbaImage,
    color_space: RgbaColorSpace,
    u: f32,
    v: f32,
) -> SampledLinearRgba {
    let x = u.rem_euclid(1.0) * image.width as f32 - 0.5;
    let y = v.rem_euclid(1.0) * image.height as f32 - 0.5;
    sample_xy_wrap_linear_linear_rgba(image, color_space, x, y)
}

fn sample_uv_clamp_linear_linear_rgba(
    image: &RgbaImage,
    color_space: RgbaColorSpace,
    u: f32,
    v: f32,
) -> SampledLinearRgba {
    let x = u * image.width as f32 - 0.5;
    let y = v * image.height as f32 - 0.5;
    sample_xy_clamp_linear_linear_rgba(image, color_space, x, y)
}

fn sample_xy_wrap_linear(image: &RgbxImage, x: f32, y: f32) -> u32 {
    let x_floor = x.floor();
    let y_floor = y.floor();
    let fx = x - x_floor;
    let fy = y - y_floor;
    let x0 = wrap_index(x_floor as isize, image.width);
    let x1 = wrap_index(x_floor as isize + 1, image.width);
    let y0 = wrap_index(y_floor as isize, image.height);
    let y1 = wrap_index(y_floor as isize + 1, image.height);
    bilinear_color(
        image.pixels[y0 * image.width + x0],
        image.pixels[y0 * image.width + x1],
        image.pixels[y1 * image.width + x0],
        image.pixels[y1 * image.width + x1],
        fx,
        fy,
    )
}

fn sample_xy_wrap_linear_rgba(image: &RgbaImage, x: f32, y: f32) -> SampledRgba {
    let x_floor = x.floor();
    let y_floor = y.floor();
    let fx = x - x_floor;
    let fy = y - y_floor;
    let x0 = wrap_index(x_floor as isize, image.width);
    let x1 = wrap_index(x_floor as isize + 1, image.width);
    let y0 = wrap_index(y_floor as isize, image.height);
    let y1 = wrap_index(y_floor as isize + 1, image.height);
    bilinear_sampled_rgba(
        rgba_pixel(image, x0, y0),
        rgba_pixel(image, x1, y0),
        rgba_pixel(image, x0, y1),
        rgba_pixel(image, x1, y1),
        fx,
        fy,
    )
}

fn sample_xy_wrap_linear_linear_rgba(
    image: &RgbaImage,
    color_space: RgbaColorSpace,
    x: f32,
    y: f32,
) -> SampledLinearRgba {
    let x_floor = x.floor();
    let y_floor = y.floor();
    let fx = x - x_floor;
    let fy = y - y_floor;
    let x0 = wrap_index(x_floor as isize, image.width);
    let x1 = wrap_index(x_floor as isize + 1, image.width);
    let y0 = wrap_index(y_floor as isize, image.height);
    let y1 = wrap_index(y_floor as isize + 1, image.height);
    bilinear_sampled_linear_rgba(
        rgba_pixel_linear(image, color_space, x0, y0),
        rgba_pixel_linear(image, color_space, x1, y0),
        rgba_pixel_linear(image, color_space, x0, y1),
        rgba_pixel_linear(image, color_space, x1, y1),
        fx,
        fy,
    )
}

fn sample_xy_clamp_linear_linear_rgba(
    image: &RgbaImage,
    color_space: RgbaColorSpace,
    x: f32,
    y: f32,
) -> SampledLinearRgba {
    let x = x.clamp(0.0, (image.width - 1) as f32);
    let y = y.clamp(0.0, (image.height - 1) as f32);
    let x0 = x.floor() as usize;
    let y0 = y.floor() as usize;
    let x1 = (x0 + 1).min(image.width - 1);
    let y1 = (y0 + 1).min(image.height - 1);
    bilinear_sampled_linear_rgba(
        rgba_pixel_linear(image, color_space, x0, y0),
        rgba_pixel_linear(image, color_space, x1, y0),
        rgba_pixel_linear(image, color_space, x0, y1),
        rgba_pixel_linear(image, color_space, x1, y1),
        x - x0 as f32,
        y - y0 as f32,
    )
}

fn rgba_pixel(image: &RgbaImage, x: usize, y: usize) -> SampledRgba {
    let offset = (y * image.width + x) * 4;
    SampledRgba {
        rgb: rgb_u32([
            image.pixels[offset],
            image.pixels[offset + 1],
            image.pixels[offset + 2],
        ]),
        alpha: f32::from(image.pixels[offset + 3]) / 255.0,
    }
}

fn rgba_pixel_linear(
    image: &RgbaImage,
    color_space: RgbaColorSpace,
    x: usize,
    y: usize,
) -> SampledLinearRgba {
    let offset = (y * image.width + x) * 4;
    let channel = |value: u8| match color_space {
        RgbaColorSpace::Linear => f32::from(value) / 255.0,
        RgbaColorSpace::Srgb => srgb_u8_to_linear_f32(value),
    };
    SampledLinearRgba {
        rgb: Vec3 {
            x: channel(image.pixels[offset]),
            y: channel(image.pixels[offset + 1]),
            z: channel(image.pixels[offset + 2]),
        },
        alpha: f32::from(image.pixels[offset + 3]) / 255.0,
    }
}

fn bilinear_sampled_rgba(
    c00: SampledRgba,
    c10: SampledRgba,
    c01: SampledRgba,
    c11: SampledRgba,
    fx: f32,
    fy: f32,
) -> SampledRgba {
    let top = mix_sampled_rgba(c00, c10, fx);
    let bottom = mix_sampled_rgba(c01, c11, fx);
    mix_sampled_rgba(top, bottom, fy)
}

fn mix_sampled_rgba(a: SampledRgba, b: SampledRgba, t: f32) -> SampledRgba {
    SampledRgba {
        rgb: mix_color(a.rgb, b.rgb, t),
        alpha: a.alpha + (b.alpha - a.alpha) * t,
    }
}

fn bilinear_sampled_linear_rgba(
    c00: SampledLinearRgba,
    c10: SampledLinearRgba,
    c01: SampledLinearRgba,
    c11: SampledLinearRgba,
    fx: f32,
    fy: f32,
) -> SampledLinearRgba {
    let top = mix_sampled_linear_rgba(c00, c10, fx);
    let bottom = mix_sampled_linear_rgba(c01, c11, fx);
    mix_sampled_linear_rgba(top, bottom, fy)
}

fn mix_sampled_linear_rgba(
    a: SampledLinearRgba,
    b: SampledLinearRgba,
    t: f32,
) -> SampledLinearRgba {
    SampledLinearRgba {
        rgb: lerp_vec3(a.rgb, b.rgb, t),
        alpha: lerp_f32(a.alpha, b.alpha, t),
    }
}

fn sample_xy_clamp_linear(image: &RgbxImage, x: f32, y: f32) -> u32 {
    let x = x.clamp(0.0, (image.width - 1) as f32);
    let y = y.clamp(0.0, (image.height - 1) as f32);
    let x0 = x.floor() as usize;
    let y0 = y.floor() as usize;
    let x1 = (x0 + 1).min(image.width - 1);
    let y1 = (y0 + 1).min(image.height - 1);
    bilinear_color(
        image.pixels[y0 * image.width + x0],
        image.pixels[y0 * image.width + x1],
        image.pixels[y1 * image.width + x0],
        image.pixels[y1 * image.width + x1],
        x - x0 as f32,
        y - y0 as f32,
    )
}

fn wrap_index(index: isize, len: usize) -> usize {
    index.rem_euclid(len as isize) as usize
}

fn bilinear_color(c00: u32, c10: u32, c01: u32, c11: u32, fx: f32, fy: f32) -> u32 {
    let top = mix_color(c00, c10, fx);
    let bottom = mix_color(c01, c11, fx);
    mix_color(top, bottom, fy)
}

fn mix_color(a: u32, b: u32, t: f32) -> u32 {
    let (ar, ag, ab) = rgb_tuple(a);
    let (br, bg, bb) = rgb_tuple(b);
    rgb_u32([
        lerp_channel(ar, br, t),
        lerp_channel(ag, bg, t),
        lerp_channel(ab, bb, t),
    ])
}

fn lerp_channel(a: u8, b: u8, t: f32) -> u8 {
    (f32::from(a) + (f32::from(b) - f32::from(a)) * t)
        .round()
        .clamp(0.0, 255.0) as u8
}

fn get_overlay(color: u32, overlay: u32, overlay_percent: f32) -> u32 {
    vec3_to_rgb_u32(get_overlay_vec3(
        rgb_to_vec3(color),
        rgb_to_vec3(overlay),
        overlay_percent,
    ))
}

fn get_overlay_vec3(color: Vec3, overlay: Vec3, overlay_percent: f32) -> Vec3 {
    Vec3 {
        x: get_overlay_channel(color.x, overlay.x, overlay_percent),
        y: get_overlay_channel(color.y, overlay.y, overlay_percent),
        z: get_overlay_channel(color.z, overlay.z, overlay_percent),
    }
}

fn get_overlay_channel(color: f32, overlay: f32, overlay_percent: f32) -> f32 {
    let color_gamma = color.clamp(0.0, 1.0).powf(0.45);
    let overlay_gamma = overlay.clamp(0.0, 1.0).powf(0.45);
    let res_gamma = if overlay_gamma < 0.5 {
        2.0 * overlay_gamma * color_gamma
    } else {
        1.0 - 2.0 * (1.0 - overlay_gamma) * (1.0 - color_gamma)
    };
    let res_linear = res_gamma.powf(2.2);
    lerp_f32(color, res_linear, overlay_percent)
}

fn rgb_to_vec3(color: u32) -> Vec3 {
    let (r, g, b) = rgb_tuple(color);
    Vec3 {
        x: f32::from(r) / 255.0,
        y: f32::from(g) / 255.0,
        z: f32::from(b) / 255.0,
    }
}

fn vec3_to_rgb_u32(color: Vec3) -> u32 {
    rgb_u32([
        (color.x.clamp(0.0, 1.0) * 255.0).round() as u8,
        (color.y.clamp(0.0, 1.0) * 255.0).round() as u8,
        (color.z.clamp(0.0, 1.0) * 255.0).round() as u8,
    ])
}

fn srgb_u8_to_linear_f32(value: u8) -> f32 {
    let encoded = f32::from(value) / 255.0;
    if encoded <= 0.04045 {
        encoded / 12.92
    } else {
        ((encoded + 0.055) / 1.055).powf(2.4)
    }
}

fn compose_water(base: u32) -> u32 {
    scale_color(base, WATER_COLOR_LIGHTNESS)
}

fn scale_color(color: u32, shade: f32) -> u32 {
    let (r, g, b) = rgb_tuple(color);
    rgb_u32([
        (f32::from(r) * shade).round().clamp(0.0, 255.0) as u8,
        (f32::from(g) * shade).round().clamp(0.0, 255.0) as u8,
        (f32::from(b) * shade).round().clamp(0.0, 255.0) as u8,
    ])
}

fn write_json<T: Serialize>(path: &Path, value: &T) -> Result<()> {
    let bytes = serde_json::to_vec_pretty(value)?;
    fs::write(path, bytes)?;
    Ok(())
}

fn write_shader_rgba_sources(
    out: &Path,
    entries: &[(&str, &str, &PathBuf)],
) -> Result<(BTreeMap<String, String>, BTreeMap<String, Dimensions>)> {
    let mut files = BTreeMap::new();
    let mut dimensions = BTreeMap::new();
    for (source, output, path) in entries {
        let image = load_dds_rgba(path)?;
        write_rgba_raw(&out.join(output), &image.pixels)?;
        files.insert((*source).to_string(), (*output).to_string());
        dimensions.insert(
            (*source).to_string(),
            Dimensions {
                width: image.width,
                height: image.height,
            },
        );
    }
    Ok((files, dimensions))
}

fn write_material_rgba_sources(
    out: &Path,
    entries: &[RgbaSourceSpec],
) -> Result<(BTreeMap<String, String>, BTreeMap<String, Dimensions>)> {
    let mut files = BTreeMap::new();
    let mut dimensions = BTreeMap::new();
    for spec in entries {
        let levels = load_dds_rgba_mips(&spec.path)?;
        let image = levels
            .first()
            .ok_or_else(|| format!("{} contains no DDS mip levels", spec.path.display()))?;
        write_rgba_raw(&out.join(&spec.output), &image.pixels)?;
        if levels.len() > 1 {
            write_rgba_mip_chain_raw(
                &out.join(shader_rgba_mip_output_name(&spec.source)),
                &levels,
            )?;
        }
        files.insert(spec.source.clone(), spec.output.clone());
        dimensions.insert(
            spec.source.clone(),
            Dimensions {
                width: image.width,
                height: image.height,
            },
        );
    }
    Ok((files, dimensions))
}

fn copy_shader_source(
    out: &Path,
    source: &str,
    output: &str,
    path: &Path,
    files: &mut BTreeMap<String, String>,
) -> Result<()> {
    fs::copy(path, out.join(output))?;
    files.insert(source.to_string(), output.to_string());
    Ok(())
}

fn copy_bundle_source(
    out: &Path,
    source: &str,
    output: &str,
    path: &Path,
    files: &mut BTreeMap<String, String>,
) -> Result<()> {
    fs::copy(path, out.join(output))?;
    files.insert(source.to_string(), output.to_string());
    Ok(())
}

fn write_u32_raw(path: &Path, values: &[u32]) -> Result<()> {
    let mut file = fs::File::create(path)?;
    let mut buf = Vec::with_capacity(values.len() * 4);
    for value in values {
        buf.extend_from_slice(&value.to_le_bytes());
    }
    file.write_all(&buf)?;
    Ok(())
}

fn write_rgba_mip_chain_raw(path: &Path, levels: &[RgbaImage]) -> Result<()> {
    let mut values = Vec::new();
    for level in levels {
        values.extend_from_slice(&level.pixels);
    }
    write_rgba_raw(path, &values)
}

fn write_u8_raw(path: &Path, values: &[u8]) -> Result<()> {
    fs::write(path, values)?;
    Ok(())
}

fn write_rgba_raw(path: &Path, values: &[u8]) -> Result<()> {
    if values.len() % 4 != 0 {
        return Err(format!("{} RGBA data is not 4-byte aligned", path.display()).into());
    }
    fs::write(path, values)?;
    Ok(())
}

fn read_u32_raw(path: &Path, expected_len: usize) -> Result<Vec<u32>> {
    let mut bytes = Vec::new();
    fs::File::open(path)?.read_to_end(&mut bytes)?;
    if bytes.len() != expected_len * 4 {
        return Err(format!(
            "{} has {} bytes, expected {}",
            path.display(),
            bytes.len(),
            expected_len * 4
        )
        .into());
    }
    Ok(bytes
        .chunks_exact(4)
        .map(|chunk| u32::from_le_bytes(chunk.try_into().expect("chunk size checked")))
        .collect())
}

fn read_rgba_raw(path: &Path, width: usize, height: usize) -> Result<RgbaImage> {
    let expected_len = checked_rgba_byte_len(width, height)?;
    let pixels = fs::read(path)?;
    if pixels.len() != expected_len {
        return Err(format!(
            "{} has {} bytes, expected {} for {}x{} RGBA",
            path.display(),
            pixels.len(),
            expected_len,
            width,
            height
        )
        .into());
    }
    Ok(RgbaImage {
        width,
        height,
        pixels,
    })
}

fn read_rgba32f_raw(path: &Path, width: usize, height: usize) -> Result<Rgba32fImage> {
    let expected_len = checked_rgba32f_byte_len(width, height)?;
    let bytes = fs::read(path)?;
    if bytes.len() != expected_len {
        return Err(format!(
            "{} has {} bytes, expected {} for {}x{} R32G32B32A32_FLOAT",
            path.display(),
            bytes.len(),
            expected_len,
            width,
            height
        )
        .into());
    }
    let pixels = bytes
        .chunks_exact(16)
        .map(|chunk| {
            [
                f32::from_le_bytes(chunk[0..4].try_into().expect("chunk size checked")),
                f32::from_le_bytes(chunk[4..8].try_into().expect("chunk size checked")),
                f32::from_le_bytes(chunk[8..12].try_into().expect("chunk size checked")),
                f32::from_le_bytes(chunk[12..16].try_into().expect("chunk size checked")),
            ]
        })
        .collect::<Vec<_>>();
    if pixels.iter().flatten().any(|value| !value.is_finite()) {
        return Err(format!(
            "production terrain renderer blocked: {} contains non-finite R32G32B32A32_FLOAT values",
            path.display()
        )
        .into());
    }
    Ok(Rgba32fImage {
        width,
        height,
        pixels,
    })
}

fn distinct_count(values: &[u32]) -> usize {
    let mut values = values.to_vec();
    values.sort_unstable();
    values.dedup();
    values.len()
}

fn visual_input_hashes(entries: &[(&str, &PathBuf)]) -> Result<BTreeMap<String, String>> {
    let mut out = BTreeMap::new();
    for (name, path) in entries {
        out.insert((*name).to_string(), fnv1a64_file(path)?);
    }
    Ok(out)
}

fn read_rgba_mip_chain_raw(
    path: &Path,
    base_width: usize,
    base_height: usize,
    mip_count: u32,
) -> Result<RgbaMipChain> {
    read_rgba_mip_chain_raw_with_color_space(
        path,
        base_width,
        base_height,
        mip_count,
        RgbaColorSpace::Linear,
    )
}

fn read_rgba_mip_chain_raw_with_color_space(
    path: &Path,
    base_width: usize,
    base_height: usize,
    mip_count: u32,
    color_space: RgbaColorSpace,
) -> Result<RgbaMipChain> {
    let level_count = mip_count.max(1) as usize;
    let mut expected_bytes = 0usize;
    for level in 0..level_count {
        let (width, height) = mip_dimensions(base_width, base_height, level);
        let level_bytes = width
            .checked_mul(height)
            .and_then(|pixels| pixels.checked_mul(4))
            .ok_or_else(|| {
                format!(
                    "{} mip-chain dimensions overflow expected byte length",
                    path.display()
                )
            })?;
        expected_bytes = expected_bytes.checked_add(level_bytes).ok_or_else(|| {
            format!(
                "{} mip-chain dimensions overflow expected byte length",
                path.display()
            )
        })?;
    }
    let pixels = fs::read(path)?;
    if pixels.len() != expected_bytes {
        return Err(format!(
            "{} has {} bytes, expected {}",
            path.display(),
            pixels.len(),
            expected_bytes
        )
        .into());
    }
    let mut levels = Vec::with_capacity(level_count);
    let mut offset = 0usize;
    for level in 0..level_count {
        let (width, height) = mip_dimensions(base_width, base_height, level);
        let len = width * height * 4;
        levels.push(RgbaImage {
            width,
            height,
            pixels: pixels[offset..offset + len].to_vec(),
        });
        offset += len;
    }
    Ok(RgbaMipChain {
        levels,
        color_space,
    })
}

fn mip_dimensions(base_width: usize, base_height: usize, level: usize) -> (usize, usize) {
    ((base_width >> level).max(1), (base_height >> level).max(1))
}

fn visual_input_dimensions(entries: &[(&str, usize, usize)]) -> BTreeMap<String, Dimensions> {
    entries
        .iter()
        .map(|(name, width, height)| {
            (
                (*name).to_string(),
                Dimensions {
                    width: *width,
                    height: *height,
                },
            )
        })
        .collect()
}

fn fnv1a64_file(path: &Path) -> Result<String> {
    let mut hash = 0xcbf29ce484222325u64;
    let mut file = fs::File::open(path)?;
    let mut buf = [0u8; 64 * 1024];
    loop {
        let n = file.read(&mut buf)?;
        if n == 0 {
            break;
        }
        for b in &buf[..n] {
            hash ^= u64::from(*b);
            hash = hash.wrapping_mul(0x100000001b3);
        }
    }
    Ok(format!("{hash:016x}"))
}

fn fnv1a64_bytes(bytes: &[u8]) -> String {
    let mut hash = 0xcbf29ce484222325u64;
    for byte in bytes {
        hash ^= u64::from(*byte);
        hash = hash.wrapping_mul(0x100000001b3);
    }
    format!("{hash:016x}")
}

fn view_bundle(bundle: &Path) -> Result<()> {
    let data = load_bundle(bundle)?;
    let mut options = WindowOptions::default();
    options.resize = true;
    options.scale_mode = ScaleMode::AspectRatioStretch;
    let mut window = Window::new("the game Rust Map Viewer", DEFAULT_W, DEFAULT_H, options)?;
    window.set_target_fps(60);

    let mut state = ViewState {
        zoom: 0.18,
        offset_x: 0.0,
        offset_y: 0.0,
        dragging: false,
        drag_x: 0.0,
        drag_y: 0.0,
        drag_offset_x: 0.0,
        drag_offset_y: 0.0,
        selected: None,
    };
    let mut screen = window.get_size();
    let mut buffer = vec![0u32; screen.0 * screen.1];
    fit_world(&mut state, &data, screen);

    while window.is_open() && !window.is_key_down(Key::Escape) {
        let new_size = window.get_size();
        if new_size != screen {
            screen = new_size;
            buffer.resize(screen.0 * screen.1, 0);
        }

        if window.is_key_pressed(Key::R, KeyRepeat::No) {
            fit_world(&mut state, &data, screen);
        }

        if let Some((_, wheel_y)) = window.get_scroll_wheel() {
            if wheel_y.abs() > f32::EPSILON {
                let mouse = window
                    .get_mouse_pos(MouseMode::Clamp)
                    .unwrap_or((screen.0 as f32 * 0.5, screen.1 as f32 * 0.5));
                zoom_at(&mut state, mouse, wheel_y);
            }
        }

        let mouse = window.get_mouse_pos(MouseMode::Clamp);
        let left_down = window.get_mouse_down(MouseButton::Left);
        if let Some((mx, my)) = mouse {
            if left_down && !state.dragging {
                state.dragging = true;
                state.drag_x = mx;
                state.drag_y = my;
                state.drag_offset_x = state.offset_x;
                state.drag_offset_y = state.offset_y;
            } else if left_down && state.dragging {
                state.offset_x = state.drag_offset_x + mx - state.drag_x;
                state.offset_y = state.drag_offset_y + my - state.drag_y;
            } else if !left_down && state.dragging {
                state.dragging = false;
                if let Some(id) = province_at_screen(&data, &state, mx, my) {
                    state.selected = Some(id);
                }
            }
            let hover = province_at_screen(&data, &state, mx, my);
            window.set_title(&probe_title(&data, hover, state.selected));
        }

        render(&data, &state, screen, &mut buffer);
        window.update_with_buffer(&buffer, screen.0, screen.1)?;
    }
    Ok(())
}

fn view_production_map_d3d11(
    terrain_map_frame_bundle: &Path,
    water_map_frame_bundle: Option<&Path>,
    rivers_map_frame_bundle: Option<&Path>,
    borders_map_frame_bundle: Option<&Path>,
    trees_map_frame_bundle: Option<&Path>,
    camera: Option<ProductionMapCamera>,
) -> Result<()> {
    let terrain_bundle = NativeD3d11TerrainBundle::load(terrain_map_frame_bundle)?;
    let water_bundle = water_map_frame_bundle
        .map(NativeD3d11TerrainBundle::load_water)
        .transpose()?;
    let rivers_bundle = rivers_map_frame_bundle
        .map(NativeD3d11TerrainBundle::load_rivers)
        .transpose()?;
    let borders_bundle = borders_map_frame_bundle
        .map(NativeD3d11TerrainBundle::load_borders)
        .transpose()?;
    let trees_bundle = trees_map_frame_bundle
        .map(NativeD3d11TerrainBundle::load_trees)
        .transpose()?;
    let renderer = NativeD3d11TerrainRenderer::new()?;
    let camera = match camera {
        Some(camera) => camera,
        None => terrain_bundle.production_camera_from_capture()?,
    };
    let camera_defines = hoi4_map_camera_defines_from_bundle(&terrain_bundle)?;
    let mut camera_state = ProductionMapCameraViewState::new(camera, camera_defines);
    let mut prepared = renderer.prepare_production_map_with_layers(
        &terrain_bundle,
        water_bundle.as_ref(),
        rivers_bundle.as_ref(),
        borders_bundle.as_ref(),
        trees_bundle.as_ref(),
        camera,
    )?;
    let mut frame = render_prepared_production_map_view_frame(&renderer, &prepared)?;

    let mut options = WindowOptions::default();
    options.resize = true;
    options.scale_mode = ScaleMode::AspectRatioStretch;
    let mut window = Window::new("the game Production Map", DEFAULT_W, DEFAULT_H, options)?;
    window.set_target_fps(60);

    while window.is_open() && !window.is_key_down(Key::Escape) {
        if update_production_map_camera_controls(&window, &mut camera_state) {
            renderer
                .update_prepared_production_map_camera(&mut prepared, camera_state.camera()?)?;
            frame = render_prepared_production_map_view_frame(&renderer, &prepared)?;
        }
        window.update_with_buffer(&frame.pixels, frame.width, frame.height)?;
    }
    Ok(())
}

fn render_prepared_production_map_view_frame(
    renderer: &NativeD3d11TerrainRenderer,
    prepared: &NativeD3d11PreparedProductionMap,
) -> Result<ProductionMapWindowFrame> {
    let options = NativeD3d11RenderOptions::default()
        .with_readback()
        .without_final_reference_comparison();
    let result = renderer.render_prepared_production_map(prepared, &options)?;
    let readback = result
        .readback
        .ok_or("production native D3D11 map viewer blocked: render produced no readback")?;
    native_d3d11_readback_to_window_frame(&readback)
}

impl ProductionMapCameraViewState {
    fn new(base: ProductionMapCamera, defines: Hoi4MapCameraDefines) -> Self {
        let mut state = Self {
            base,
            defines,
            zoom: 1.0,
            pan_clip_x: 0.0,
            pan_clip_y: 0.0,
            dragging: false,
            drag_x: 0.0,
            drag_y: 0.0,
            drag_pan_clip_x: 0.0,
            drag_pan_clip_y: 0.0,
        };
        state.zoom = state.clamp_zoom(1.0);
        state
    }

    fn reset(&mut self) {
        self.zoom = self.clamp_zoom(1.0);
        self.pan_clip_x = 0.0;
        self.pan_clip_y = 0.0;
        self.dragging = false;
    }

    fn camera(&self) -> Result<ProductionMapCamera> {
        let zoom = self.clamp_zoom(self.zoom);
        let matrix = production_map_camera_clip_transform(
            self.base.view_projection_matrix,
            zoom,
            self.pan_clip_x,
            self.pan_clip_y,
        );
        let mut position = self.base.position;
        position[1] = self.camera_height_for_zoom(zoom);
        ProductionMapCamera::new(matrix, position)
    }

    fn zoom_bounds(&self) -> (f32, f32) {
        let base_height = self
            .base
            .position
            .get(1)
            .copied()
            .filter(|value| value.is_finite() && *value > 0.0)
            .unwrap_or(self.defines.max_height);
        let min_zoom = (base_height / self.defines.max_height).max(f32::MIN_POSITIVE);
        let max_zoom = (base_height / self.defines.min_height).max(min_zoom);
        (min_zoom, max_zoom)
    }

    fn clamp_zoom(&self, zoom: f32) -> f32 {
        let (min_zoom, max_zoom) = self.zoom_bounds();
        let zoom = if zoom.is_finite() && zoom > 0.0 {
            zoom
        } else {
            1.0
        };
        zoom.clamp(min_zoom, max_zoom)
    }

    fn camera_height_for_zoom(&self, zoom: f32) -> f32 {
        let zoom = self.clamp_zoom(zoom);
        (self.base.position[1] / zoom).clamp(self.defines.min_height, self.defines.max_height)
    }

    fn camera_height_fraction(&self) -> f32 {
        let height = self.camera_height_for_zoom(self.zoom);
        ((height - self.defines.min_height) / (self.defines.max_height - self.defines.min_height))
            .clamp(0.0, 1.0)
    }

    fn camera_define_distance_multiplier(&self) -> f32 {
        let extra = (self.defines.zoom_speed_distance_mult - 1.0).max(0.0);
        1.0 + extra * self.camera_height_fraction()
    }

    fn camera_define_input_step(&self) -> f32 {
        let step = self.defines.zoom_speed
            * self.defines.zoom_key_scale
            * self.camera_define_distance_multiplier()
            / PRODUCTION_CAMERA_CONTROL_UPDATE_HZ;
        if step.is_finite() {
            step.max(0.0)
        } else {
            0.0
        }
    }

    fn edge_pan_threshold_px(&self, window_size: (usize, usize)) -> f32 {
        let min_dim = window_size.0.min(window_size.1) as f32;
        let threshold = min_dim * self.defines.zoom_key_scale;
        if threshold.is_finite() && threshold > 0.0 {
            threshold.min(min_dim * 0.5)
        } else {
            0.0
        }
    }

    fn zoom_at(&mut self, window_size: (usize, usize), mouse: (f32, f32), wheel_y: f32) {
        let old_zoom = self.clamp_zoom(self.zoom);
        let step = self.camera_define_input_step();
        if step <= 0.0 {
            return;
        }
        let factor = (1.0 + step).powf(wheel_y.abs());
        let next_zoom = if !factor.is_finite() || factor <= 0.0 {
            let (min_zoom, max_zoom) = self.zoom_bounds();
            if wheel_y > 0.0 {
                max_zoom
            } else {
                min_zoom
            }
        } else if wheel_y > 0.0 {
            old_zoom * factor
        } else {
            old_zoom / factor
        };
        self.zoom = self.clamp_zoom(next_zoom);
        let actual_factor = self.zoom / old_zoom;
        if (actual_factor - 1.0).abs() <= f32::EPSILON {
            return;
        }
        let cursor_clip_x = mouse.0 / window_size.0.max(1) as f32 * 2.0 - 1.0;
        let cursor_clip_y = 1.0 - mouse.1 / window_size.1.max(1) as f32 * 2.0;
        self.pan_clip_x = cursor_clip_x - actual_factor * (cursor_clip_x - self.pan_clip_x);
        self.pan_clip_y = cursor_clip_y - actual_factor * (cursor_clip_y - self.pan_clip_y);
    }
}

fn update_production_map_camera_controls(
    window: &Window,
    state: &mut ProductionMapCameraViewState,
) -> bool {
    let mut changed = false;
    let window_size = window.get_size();

    if window.is_key_pressed(Key::R, KeyRepeat::No) {
        state.reset();
        changed = true;
    }

    if let Some((_, wheel_y)) = window.get_scroll_wheel() {
        if wheel_y.abs() > f32::EPSILON {
            let mouse = window
                .get_mouse_pos(MouseMode::Clamp)
                .unwrap_or((window_size.0 as f32 * 0.5, window_size.1 as f32 * 0.5));
            state.zoom_at(window_size, mouse, wheel_y);
            changed = true;
        }
    }

    let drag_down =
        window.get_mouse_down(MouseButton::Right) || window.get_mouse_down(MouseButton::Middle);
    if let Some((mx, my)) = window.get_mouse_pos(MouseMode::Clamp) {
        if drag_down && !state.dragging {
            state.dragging = true;
            state.drag_x = mx;
            state.drag_y = my;
            state.drag_pan_clip_x = state.pan_clip_x;
            state.drag_pan_clip_y = state.pan_clip_y;
        } else if drag_down && state.dragging {
            state.pan_clip_x =
                state.drag_pan_clip_x + (mx - state.drag_x) * 2.0 / window_size.0.max(1) as f32;
            state.pan_clip_y =
                state.drag_pan_clip_y - (my - state.drag_y) * 2.0 / window_size.1.max(1) as f32;
            changed = true;
        } else if !drag_down && state.dragging {
            state.dragging = false;
        }

        let edge = state.edge_pan_threshold_px(window_size);
        let edge_step = state.camera_define_input_step();
        if edge_step > 0.0 {
            if mx <= edge {
                state.pan_clip_x += edge_step;
                changed = true;
            } else if mx >= window_size.0 as f32 - edge {
                state.pan_clip_x -= edge_step;
                changed = true;
            }
            if my <= edge {
                state.pan_clip_y -= edge_step;
                changed = true;
            } else if my >= window_size.1 as f32 - edge {
                state.pan_clip_y += edge_step;
                changed = true;
            }
        }
    } else {
        state.dragging = false;
    }

    let key_step = state.camera_define_input_step();
    if key_step > 0.0 {
        if window.is_key_down(Key::A) || window.is_key_down(Key::Left) {
            state.pan_clip_x += key_step;
            changed = true;
        }
        if window.is_key_down(Key::D) || window.is_key_down(Key::Right) {
            state.pan_clip_x -= key_step;
            changed = true;
        }
        if window.is_key_down(Key::W) || window.is_key_down(Key::Up) {
            state.pan_clip_y -= key_step;
            changed = true;
        }
        if window.is_key_down(Key::S) || window.is_key_down(Key::Down) {
            state.pan_clip_y += key_step;
            changed = true;
        }
    }

    changed
}

fn production_map_camera_clip_transform(
    base: [[f32; 4]; 4],
    zoom: f32,
    pan_clip_x: f32,
    pan_clip_y: f32,
) -> [[f32; 4]; 4] {
    let mut matrix = base;
    for column in 0..4 {
        matrix[0][column] = base[0][column] * zoom + base[3][column] * pan_clip_x;
        matrix[1][column] = base[1][column] * zoom + base[3][column] * pan_clip_y;
    }
    matrix
}

fn native_d3d11_readback_to_window_frame(
    readback: &NativeD3d11ReplayReadback,
) -> Result<ProductionMapWindowFrame> {
    let width = usize::try_from(readback.width)?;
    let height = usize::try_from(readback.height)?;
    let pixel_count = width
        .checked_mul(height)
        .ok_or("production native D3D11 map viewer blocked: readback pixel count overflow")?;
    let row_pitch = usize::try_from(readback.row_pitch)?;
    let expected_len = row_pitch
        .checked_mul(height)
        .ok_or("production native D3D11 map viewer blocked: readback byte count overflow")?;
    if readback.bytes.len() != expected_len {
        return Err(format!(
            "production native D3D11 map viewer blocked: readback has {} bytes, expected {}",
            readback.bytes.len(),
            expected_len
        )
        .into());
    }

    let mut pixels = Vec::with_capacity(pixel_count);
    match readback.dxgi_format {
        DXGI_FORMAT_R8G8B8A8_UNORM => {
            for chunk in readback.bytes.chunks_exact(4) {
                pixels.push(window_rgb(chunk[0], chunk[1], chunk[2]));
            }
        }
        DXGI_FORMAT_B8G8R8A8_UNORM
        | DXGI_FORMAT_B8G8R8A8_UNORM_SRGB
        | DXGI_FORMAT_B8G8R8X8_UNORM => {
            for chunk in readback.bytes.chunks_exact(4) {
                pixels.push(window_rgb(chunk[2], chunk[1], chunk[0]));
            }
        }
        DXGI_FORMAT_R16G16B16A16_FLOAT => {
            for chunk in readback.bytes.chunks_exact(8) {
                let r = half_float_to_unorm8(u16::from_le_bytes([chunk[0], chunk[1]]));
                let g = half_float_to_unorm8(u16::from_le_bytes([chunk[2], chunk[3]]));
                let b = half_float_to_unorm8(u16::from_le_bytes([chunk[4], chunk[5]]));
                pixels.push(window_rgb(r, g, b));
            }
        }
        other => {
            return Err(format!(
            "production native D3D11 map viewer blocked: unsupported readback DXGI format {other}"
        )
            .into())
        }
    }
    if pixels.len() != pixel_count {
        return Err(format!(
            "production native D3D11 map viewer blocked: converted {} pixels, expected {}",
            pixels.len(),
            pixel_count
        )
        .into());
    }
    Ok(ProductionMapWindowFrame {
        width,
        height,
        pixels,
    })
}

fn window_rgb(r: u8, g: u8, b: u8) -> u32 {
    (u32::from(r) << 16) | (u32::from(g) << 8) | u32::from(b)
}

fn half_float_to_unorm8(bits: u16) -> u8 {
    let value = half_float_to_f32(bits);
    if !value.is_finite() {
        return if value.is_sign_positive() { 255 } else { 0 };
    }
    (value.clamp(0.0, 1.0) * 255.0).round() as u8
}

fn half_float_to_f32(bits: u16) -> f32 {
    let sign = if bits & 0x8000 == 0 { 1.0 } else { -1.0 };
    let exponent = (bits >> 10) & 0x1f;
    let fraction = bits & 0x03ff;
    match exponent {
        0 => {
            if fraction == 0 {
                sign * 0.0
            } else {
                sign * 2.0f32.powi(-14) * (f32::from(fraction) / 1024.0)
            }
        }
        0x1f => {
            if fraction == 0 {
                sign * f32::INFINITY
            } else {
                f32::NAN
            }
        }
        _ => sign * 2.0f32.powi(i32::from(exponent) - 15) * (1.0 + f32::from(fraction) / 1024.0),
    }
}

fn load_bundle(bundle: &Path) -> Result<BundleData> {
    let manifest: Manifest = serde_json::from_slice(&fs::read(bundle.join("manifest.json"))?)?;
    if manifest.schema != "battle-plan-rust-map-bundle-v1" {
        return Err(format!("unsupported map bundle schema: {}", manifest.schema).into());
    }
    let len = manifest.dimensions.width * manifest.dimensions.height;
    Ok(BundleData {
        province_ids: read_u32_raw(&bundle.join(&manifest.files.province_ids), len)?,
        visual: read_u32_raw(&bundle.join(&manifest.files.map_visual), len)?,
        province_to_state: serde_json::from_slice(&fs::read(
            bundle.join(&manifest.files.province_to_state),
        )?)?,
        province_to_region: serde_json::from_slice(&fs::read(
            bundle.join(&manifest.files.province_to_strategic_region),
        )?)?,
        state_owners: serde_json::from_slice(&fs::read(
            bundle.join(&manifest.files.state_owner_1936),
        )?)?,
        state_meta: serde_json::from_slice(&fs::read(bundle.join(&manifest.files.state_meta))?)?,
        province_defs: serde_json::from_slice(&fs::read(
            bundle.join(&manifest.files.province_definitions),
        )?)?,
        manifest,
    })
}

fn validate_production_terrain_renderer(bundle: &Path) -> Result<TerrainRendererInputs> {
    validate_production_terrain_renderer_impl(bundle, true)
}

fn validate_production_terrain_renderer_for_map_frame(
    bundle: &Path,
) -> Result<TerrainRendererInputs> {
    validate_production_terrain_renderer_impl(bundle, false)
}

fn validate_production_terrain_renderer_impl(
    bundle: &Path,
    require_legacy_runtime_draw_inputs: bool,
) -> Result<TerrainRendererInputs> {
    let manifest: Manifest = serde_json::from_slice(&fs::read(bundle.join("manifest.json"))?)?;
    if manifest.schema != "battle-plan-rust-map-bundle-v1" {
        return Err(format!("unsupported map bundle schema: {}", manifest.schema).into());
    }
    let contract: MapMaterialContract = serde_json::from_slice(&fs::read(
        bundle.join(&manifest.files.map_material_contract),
    )?)?;
    let (terrain_id_map, terrain_runtime, runtime) = if require_legacy_runtime_draw_inputs {
        let terrain_id_map = bundle.join(&manifest.files.terrain_id_map);
        if !terrain_id_map.is_file() {
            return Err(format!(
                "production terrain renderer blocked: missing {}. the game pdxmap.shader samples TerrainIDMap before atlas blending; no fallback from terrain.bmp is allowed.",
                manifest.files.terrain_id_map
            )
            .into());
        }
        let terrain_runtime = required_bundle_file(
            bundle,
            "terrain runtime input contract",
            &manifest.files.terrain_runtime,
        )?;
        let runtime: TerrainRuntimeInputs = serde_json::from_slice(&fs::read(&terrain_runtime)?)?;
        validate_terrain_runtime_inputs(&runtime, &manifest, bundle, &terrain_id_map)?;
        (Some(terrain_id_map), Some(terrain_runtime), Some(runtime))
    } else {
        (None, None, None)
    };
    if !contract
        .generated_runtime_inputs
        .contains_key("terrain_id_map")
    {
        return Err("production terrain renderer blocked: material contract does not classify TerrainIDMap provenance".into());
    }

    let inputs = TerrainRendererInputs {
        terrain_runtime,
        terrain_id_map,
        terrain_diffuse_atlas: required_shader_source_path(
            bundle,
            &manifest,
            "map/terrain/atlas0.dds",
        )?,
        terrain_normal_atlas: required_shader_source_path(
            bundle,
            &manifest,
            "map/terrain/atlas_normal0.dds",
        )?,
        terrain_diffuse_atlas_mips: required_bundle_file(
            bundle,
            "terrain diffuse atlas mip chain",
            &manifest.files.terrain_diffuse_atlas_mips,
        )?,
        terrain_normal_atlas_mips: required_bundle_file(
            bundle,
            "terrain normal atlas mip chain",
            &manifest.files.terrain_normal_atlas_mips,
        )?,
        terrain_color_tint: required_shader_source_path(
            bundle,
            &manifest,
            "map/terrain/colormap_rgb_cityemissivemask_a.dds",
        )?,
        height_normal: required_bundle_file(
            bundle,
            "height_normal",
            &manifest.files.height_normal,
        )?,
        constants_source: required_map_source_path(bundle, &manifest, "gfx/FX/constants.fxh")?,
        pdxmap_shader_source: required_map_source_path(bundle, &manifest, "gfx/FX/pdxmap.shader")?,
        pdxmap_include_source: required_map_source_path(bundle, &manifest, "gfx/FX/pdxmap.fxh")?,
        standard_functions_source: required_map_source_path(
            bundle,
            &manifest,
            "gfx/FX/standardfuncsgfx.fxh",
        )?,
        shadow_include_source: required_map_source_path(bundle, &manifest, "gfx/FX/shadow.fxh")?,
        fow_include_source: required_map_source_path(bundle, &manifest, "gfx/FX/fow.fxh")?,
        runtime,
    };
    validate_pdxmap_sampler_contract(&inputs.pdxmap_shader_source)?;
    validate_standard_function_shader_constant(
        &inputs.standard_functions_source,
        "NIGHT_OPACITY",
        NIGHT_OPACITY,
    )?;
    validate_standard_function_shader_constant(
        &inputs.standard_functions_source,
        "NIGHT_DARKNESS",
        NIGHT_DARKNESS,
    )?;
    validate_shader_source_vector3_constant(
        &inputs.fow_include_source,
        "gfx/FX/fow.fxh",
        "BRIGHT_FOW_COLOR",
        BRIGHT_FOW_COLOR,
    )?;
    validate_shader_source_vector3_constant(
        &inputs.fow_include_source,
        "gfx/FX/fow.fxh",
        "DARK_FOW_COLOR",
        DARK_FOW_COLOR,
    )?;
    if let Some(runtime) = &inputs.runtime {
        validate_runtime_texture_sampler_contract(runtime, &inputs.pdxmap_shader_source)?;
    }
    validate_material_mip_outputs(&contract, bundle)?;
    validate_shader_constant(&contract, "TERRAIN_TILE_FREQ", TERRAIN_TILE_FREQ)?;
    validate_shader_constant(&contract, "TEXELS_PER_TILE", TEXELS_PER_TILE)?;
    validate_shader_constant(&contract, "MAP_NUM_TILES", MAP_NUM_TILES as f32)?;
    validate_shader_constant(
        &contract,
        "ATLAS_TEXEL_POW2_EXPONENT",
        ATLAS_TEXEL_POW2_EXPONENT,
    )?;
    validate_shader_constant(
        &contract,
        "COLORMAP_OVERLAY_STRENGTH",
        COLORMAP_OVERLAY_STRENGTH,
    )?;
    validate_shader_constant(
        &contract,
        "COLORMAP_MUD_OVERLAY_STRENGTH",
        COLORMAP_MUD_OVERLAY_STRENGTH,
    )?;
    validate_shader_constant(&contract, "MUD_TILING", MUD_TILING)?;
    validate_shader_constant(&contract, "MUD_NORMAL_CUTOFF", MUD_NORMAL_CUTOFF)?;
    validate_shader_constant(&contract, "MUD_STRENGHTEN", MUD_STRENGHTEN)?;
    validate_shader_constant(&contract, "MUD_CAM_MIN", MUD_CAM_MIN)?;
    validate_shader_constant(&contract, "MUD_CAM_MAX", MUD_CAM_MAX)?;
    validate_shader_constant(&contract, "SNOW_OPACITY_MIN", SNOW_OPACITY_MIN)?;
    validate_shader_constant(&contract, "SNOW_OPACITY_MAX", SNOW_OPACITY_MAX)?;
    validate_shader_constant(&contract, "SNOW_CAM_MIN", SNOW_CAM_MIN)?;
    validate_shader_constant(&contract, "SNOW_CAM_MAX", SNOW_CAM_MAX)?;
    validate_shader_constant(&contract, "SNOW_START_HEIGHT", SNOW_START_HEIGHT)?;
    validate_shader_constant(
        &contract,
        "SNOW_RIDGE_START_HEIGHT",
        SNOW_RIDGE_START_HEIGHT,
    )?;
    validate_shader_constant(&contract, "SNOW_NORMAL_START", SNOW_NORMAL_START)?;
    validate_shader_constant(&contract, "SNOW_CLIFFS", SNOW_CLIFFS)?;
    validate_shader_constant(&contract, "SNOW_SPEC_GLOSS_MULT", SNOW_SPEC_GLOSS_MULT)?;
    validate_shader_constant(&contract, "SNOW_TILING", SNOW_TILING)?;
    validate_shader_constant(&contract, "SNOW_NOISE_TILING", SNOW_NOISE_TILING)?;
    validate_shader_constant(&contract, "SNOW_FROST_MIN_EFFECT", SNOW_FROST_MIN_EFFECT)?;
    validate_shader_constant(&contract, "CITY_LIGHTS_TILING", CITY_LIGHTS_TILING)?;
    validate_shader_constant(&contract, "CITY_LIGHTS_INTENSITY", CITY_LIGHTS_INTENSITY)?;
    validate_shader_constant(&contract, "FOG_BEGIN", FOG_BEGIN)?;
    validate_shader_constant(&contract, "FOG_END", FOG_END)?;
    validate_shader_constant(&contract, "FOG_MAX", FOG_MAX)?;
    validate_shader_constant(&contract, "GB_CAM_MIN", GB_CAM_MIN)?;
    validate_shader_constant(&contract, "GB_CAM_MAX", GB_CAM_MAX)?;
    validate_shader_constant(
        &contract,
        "GB_CAM_MAX_FILLING_CLAMP",
        GB_CAM_MAX_FILLING_CLAMP,
    )?;
    validate_shader_constant(&contract, "GB_THRESHOLD", GB_THRESHOLD)?;
    validate_shader_constant(&contract, "GB_THRESHOLD2", GB_THRESHOLD2)?;
    validate_shader_constant(&contract, "GB_OPACITY_NEAR", GB_OPACITY_NEAR)?;
    validate_shader_constant(&contract, "GB_OPACITY_FAR", GB_OPACITY_FAR)?;
    validate_shader_constant(&contract, "GB_STRENGTH_CH1", GB_STRENGTH_CH1)?;
    validate_shader_constant(&contract, "GB_STRENGTH_CH2", GB_STRENGTH_CH2)?;
    validate_shader_constant(
        &contract,
        "GB_FIRST_LAYER_PRIORITY",
        GB_FIRST_LAYER_PRIORITY,
    )?;
    validate_shader_constant(&contract, "SEC_MAP_TILE", SEC_MAP_TILE)?;
    validate_shader_constant(
        &contract,
        "BORDER_NIGHT_DESATURATION_MAX",
        BORDER_NIGHT_DESATURATION_MAX,
    )?;
    validate_shader_constant(
        &contract,
        "BORDER_FOW_REMOVAL_FACTOR",
        BORDER_FOW_REMOVAL_FACTOR,
    )?;
    validate_shader_constant(
        &contract,
        "BORDER_LIGHT_REMOVAL_FACTOR",
        BORDER_LIGHT_REMOVAL_FACTOR,
    )?;
    validate_shader_vector3_constant(&contract, "SNOW_COLOR", SNOW_COLOR)?;
    validate_shader_vector3_constant(&contract, "FOG_COLOR", FOG_COLOR)?;
    if require_legacy_runtime_draw_inputs {
        let runtime = inputs
            .runtime
            .as_ref()
            .ok_or("production terrain renderer blocked: missing legacy terrain runtime inputs")?;
        validate_required_runtime_renderer_inputs(runtime)?;
    }
    Ok(inputs)
}

fn validate_map_frame_runtime_bundle(path: &Path) -> Result<MapFrameRuntimeBundle> {
    validate_map_frame_runtime_bundle_for(path, TERRAIN_MAP_FRAME_SPEC)
}

pub fn validate_water_map_frame_bundle(path: &Path) -> Result<()> {
    validate_map_frame_runtime_bundle_for(path, WATER_MAP_FRAME_SPEC).map(|_| ())
}

pub fn validate_rivers_map_frame_bundle(path: &Path) -> Result<()> {
    validate_map_frame_runtime_bundle_for(path, RIVERS_MAP_FRAME_SPEC).map(|_| ())
}

pub fn validate_borders_map_frame_bundle(path: &Path) -> Result<()> {
    validate_map_frame_runtime_bundle_for(path, BORDERS_MAP_FRAME_SPEC).map(|_| ())
}

pub fn validate_trees_map_frame_bundle(path: &Path) -> Result<()> {
    validate_map_frame_runtime_bundle_for(path, TREES_MAP_FRAME_SPEC).map(|_| ())
}

fn validate_map_frame_runtime_bundle_for(
    path: &Path,
    spec: MapFrameBundleValidationSpec,
) -> Result<MapFrameRuntimeBundle> {
    let manifest_path = map_frame_bundle_manifest_path_for(path, spec);
    let bundle_dir = map_frame_bundle_dir_for(path, spec)?;
    if !manifest_path.exists() {
        return Err(
            map_capture_session_blocker_error_for(&bundle_dir, spec).unwrap_or_else(|| {
                format!(
                    "{} blocked: map-frame bundle {} is missing",
                    spec.renderer_label,
                    manifest_path.display()
                )
                .into()
            }),
        );
    }
    let frame: MapFrameRuntimeBundle = serde_json::from_slice(&fs::read(&manifest_path)?)?;
    if frame.schema != MAP_FRAME_BUNDLE_SCHEMA {
        return Err(format!(
            "{} blocked: unsupported map-frame bundle schema {}",
            spec.renderer_label, frame.schema
        )
        .into());
    }
    let extraction_blockers = effective_map_frame_extraction_blockers(&frame, spec);
    if !extraction_blockers.is_empty() {
        return Err(format!(
            "{} blocked: map-frame extraction reported blocker(s): {}",
            spec.renderer_label,
            extraction_blockers.join("; ")
        )
        .into());
    }
    validate_map_capture_session_manifest_for(&frame, &bundle_dir, spec)?;
    if frame.draws.len() < spec.min_draws {
        return Err(format!(
            "{} blocked: map-frame bundle has {} draw record(s), expected at least {} for {}",
            spec.renderer_label,
            frame.draws.len(),
            spec.min_draws,
            spec.capture_moment
        )
        .into());
    }
    if !frame.draws.iter().any(|draw| {
        draw.draw_index == frame.active_draw.draw_index
            && draw.draw_call == frame.active_draw.draw_call
            && draw.draw_count == frame.active_draw.draw_count
            && draw.draw_start == frame.active_draw.draw_start
    }) {
        return Err(format!(
            "{} blocked: active_draw is not present in map-frame draws sequence",
            spec.renderer_label
        )
        .into());
    }
    if spec.terrain_strict {
        validate_map_frame_shader_cache_constants_evidence(&frame)?;
    }
    validate_map_frame_vanilla_sources(&frame, &bundle_dir, spec)?;
    for draw in &frame.draws {
        validate_map_frame_draw(draw, &frame, &bundle_dir, spec)?;
    }
    validate_map_frame_resources(&frame, &bundle_dir, spec)?;
    Ok(frame)
}

fn effective_map_frame_extraction_blockers(
    frame: &MapFrameRuntimeBundle,
    spec: MapFrameBundleValidationSpec,
) -> Vec<String> {
    effective_extraction_blockers(&frame.blockers, spec)
}

fn effective_extraction_blockers(
    blockers: &[String],
    spec: MapFrameBundleValidationSpec,
) -> Vec<String> {
    blockers
        .iter()
        .filter(|blocker| {
            !(spec.ignore_dependent_pre_draw_output_blockers
                && is_dependent_pre_draw_output_blocker(blocker))
        })
        .cloned()
        .collect()
}

fn is_dependent_pre_draw_output_blocker(blocker: &str) -> bool {
    let lower = blocker.to_ascii_lowercase();
    let mentions_pre_draw_output = lower.contains("pre-draw om render target")
        || lower.contains("pre-draw om depth-stencil")
        || lower.contains("pre-draw output-merger render target")
        || lower.contains("pre-draw output-merger depth-stencil");
    mentions_pre_draw_output
        && (lower.contains("payload")
            || lower.contains("resolved readback")
            || lower.contains("readback"))
}

fn validate_map_frame_shader_cache_constants_evidence(frame: &MapFrameRuntimeBundle) -> Result<()> {
    let Some(constants) = &frame.shader_cache_constants else {
        return Ok(());
    };
    let terrain_slot = frame
        .active_draw
        .shader
        .reflection_resources
        .get(TERRAIN_ID_RESOURCE_SYMBOL)
        .copied()
        .ok_or("production terrain renderer blocked: active shader reflection does not declare TerrainIDMap for shader-cache constants")?;
    if constants.terrain_id_srv_slot != terrain_slot {
        return Err(format!(
            "production terrain renderer blocked: map-frame shader-cache constants name TerrainIDMap t{}, but active shader reflection declares t{}",
            constants.terrain_id_srv_slot, terrain_slot
        )
        .into());
    }
    let terrain_srv = map_frame_terrain_srv(&frame.active_draw)?;
    if constants.map_size_x.round() as u32 != terrain_srv.width
        || constants.map_size_y.round() as u32 != terrain_srv.height
    {
        return Err(format!(
            "production terrain renderer blocked: map-frame shader-cache MAP_SIZE {}x{} does not match captured TerrainIDMap {}x{}",
            constants.map_size_x, constants.map_size_y, terrain_srv.width, terrain_srv.height
        )
        .into());
    }
    if constants.cache_files.is_empty()
        || constants.provenance.trim().is_empty()
        || constants.extraction.trim().is_empty()
    {
        return Err(
            "production terrain renderer blocked: map-frame shader-cache constants must include cache file provenance and extraction"
                .into(),
        );
    }
    validate_map_frame_shader_constants(MapFrameTerrainShaderConstants {
        map_size_x: constants.map_size_x,
        map_size_y: constants.map_size_y,
        map_pow2_x: constants.map_pow2_x,
        map_pow2_y: constants.map_pow2_y,
        fow_pow2_x: constants.fow_pow2_x,
        fow_pow2_y: constants.fow_pow2_y,
    })
}

fn map_capture_session_blocker_error_for(
    bundle_dir: &Path,
    spec: MapFrameBundleValidationSpec,
) -> Option<Box<dyn Error>> {
    let session_path = bundle_dir.join(MAP_CAPTURE_SESSION_FILE);
    let session: MapCaptureSession = serde_json::from_slice(&fs::read(&session_path).ok()?).ok()?;
    if session.schema != MAP_CAPTURE_SESSION_SCHEMA {
        return None;
    }
    let moment = session
        .moments
        .iter()
        .find(|moment| moment.name == spec.capture_moment)?;
    if moment.status != "blocked" {
        return None;
    }
    let blockers = if moment.blockers.is_empty() {
        "no blocker details recorded".to_string()
    } else {
        moment.blockers.join("; ")
    };
    Some(
        format!(
            "{} blocked: map capture session {} is blocked before {} exists: {blockers}",
            spec.renderer_label, spec.capture_moment, spec.bundle_file
        )
        .into(),
    )
}

fn validate_map_capture_session_manifest_for(
    frame: &MapFrameRuntimeBundle,
    bundle_dir: &Path,
    spec: MapFrameBundleValidationSpec,
) -> Result<()> {
    if frame.capture_moment != spec.capture_moment {
        return Err(format!(
            "{} blocked: map-frame bundle capture moment {} is not {}",
            spec.renderer_label, frame.capture_moment, spec.capture_moment
        )
        .into());
    }
    if frame.session_manifest != MAP_CAPTURE_SESSION_FILE {
        return Err(format!(
            "{} blocked: map-frame bundle must cite session manifest {MAP_CAPTURE_SESSION_FILE}",
            spec.renderer_label
        )
        .into());
    }
    let session_path = bundle_dir.join(&frame.session_manifest);
    let session_bytes = fs::read(&session_path).map_err(|error| {
        format!(
            "{} blocked: map-frame bundle session manifest {} is missing or unreadable: {error}",
            spec.renderer_label, frame.session_manifest
        )
    })?;
    let session: MapCaptureSession = serde_json::from_slice(&session_bytes)?;
    if session.schema != MAP_CAPTURE_SESSION_SCHEMA {
        return Err(format!(
            "{} blocked: unsupported map capture session schema {}",
            spec.renderer_label, session.schema
        )
        .into());
    }
    if session.required_first_moment != TERRAIN_CAPTURE_MOMENT {
        return Err(format!(
            "{} blocked: map capture session first moment {} is not {}",
            spec.renderer_label, session.required_first_moment, TERRAIN_CAPTURE_MOMENT
        )
        .into());
    }
    let moment = session
        .moments
        .iter()
        .find(|moment| moment.name == spec.capture_moment)
        .ok_or_else(|| {
            format!(
                "{} blocked: map capture session is missing {} moment",
                spec.renderer_label, spec.capture_moment
            )
        })?;
    let moment_blockers = effective_extraction_blockers(&moment.blockers, spec);
    let only_ignored_dependent_pre_draw_blockers = spec.ignore_dependent_pre_draw_output_blockers
        && moment.status == "blocked"
        && !moment.blockers.is_empty()
        && moment_blockers.is_empty();
    if moment.status != "captured_pending_renderer_validation"
        && !only_ignored_dependent_pre_draw_blockers
    {
        return Err(format!(
            "{} blocked: map capture session {} moment status is {}",
            spec.renderer_label, spec.capture_moment, moment.status
        )
        .into());
    }
    if moment.bundle_file != spec.bundle_file {
        return Err(format!(
            "{} blocked: map capture session {} moment points to {}, expected {}",
            spec.renderer_label, spec.capture_moment, moment.bundle_file, spec.bundle_file
        )
        .into());
    }
    for required in MAP_CAPTURE_REQUIRED_PAYLOAD {
        if !moment
            .required_payload
            .iter()
            .any(|payload| payload == required)
        {
            return Err(format!(
                "{} blocked: map capture session {} moment is missing required payload {required}",
                spec.renderer_label, spec.capture_moment
            )
            .into());
        }
    }
    if !moment_blockers.is_empty() {
        return Err(format!(
            "{} blocked: map capture session {} moment reported blocker(s): {}",
            spec.renderer_label,
            spec.capture_moment,
            moment_blockers.join("; ")
        )
        .into());
    }
    if spec.capture_moment != TERRAIN_CAPTURE_MOMENT {
        let terrain_moment = session
            .moments
            .iter()
            .find(|moment| moment.name == TERRAIN_CAPTURE_MOMENT)
            .ok_or_else(|| {
                format!(
                    "{} blocked: map capture session for {} is missing required prior terrain moment",
                    spec.renderer_label, spec.capture_moment
                )
            })?;
        if terrain_moment.status != "captured_pending_renderer_validation" {
            return Err(format!(
                "{} blocked: map capture session for {} requires terrain moment status captured_pending_renderer_validation, got {}",
                spec.renderer_label, spec.capture_moment, terrain_moment.status
            )
            .into());
        }
        return Ok(());
    }
    for deferred in &session.deferred_moments {
        if deferred.required_after != TERRAIN_CAPTURE_MOMENT {
            return Err(format!(
                "{} blocked: deferred capture moment {} is not gated behind {}",
                spec.renderer_label, deferred.name, TERRAIN_CAPTURE_MOMENT
            )
            .into());
        }
        if deferred.status != "deferred_until_terrain_active_pass_validated" {
            return Err(format!(
                "{} blocked: deferred capture moment {} has unsupported status {}",
                spec.renderer_label, deferred.name, deferred.status
            )
            .into());
        }
    }
    Ok(())
}

fn map_frame_bundle_manifest_path(path: &Path) -> PathBuf {
    map_frame_bundle_manifest_path_for(path, TERRAIN_MAP_FRAME_SPEC)
}

fn map_frame_bundle_manifest_path_for(path: &Path, spec: MapFrameBundleValidationSpec) -> PathBuf {
    if path.is_dir() {
        path.join(spec.bundle_file)
    } else {
        path.to_path_buf()
    }
}

fn map_frame_bundle_dir(path: &Path) -> Result<PathBuf> {
    map_frame_bundle_dir_for(path, TERRAIN_MAP_FRAME_SPEC)
}

fn map_frame_bundle_dir_for(path: &Path, spec: MapFrameBundleValidationSpec) -> Result<PathBuf> {
    let manifest_path = map_frame_bundle_manifest_path_for(path, spec);
    Ok(manifest_path
        .parent()
        .ok_or_else(|| {
            format!(
                "{} blocked: {} has no parent directory",
                spec.renderer_label,
                manifest_path.display()
            )
        })?
        .to_path_buf())
}

fn validate_map_frame_draw(
    draw: &MapFrameDraw,
    frame: &MapFrameRuntimeBundle,
    bundle_dir: &Path,
    spec: MapFrameBundleValidationSpec,
) -> Result<()> {
    if !matches!(
        draw.draw_call.as_str(),
        "Draw" | "DrawIndexed" | "DrawInstanced" | "DrawIndexedInstanced"
    ) {
        return Err(format!(
            "{} blocked: unsupported map-frame draw call {}",
            spec.renderer_label, draw.draw_call
        )
        .into());
    }
    if draw.draw_count == 0 {
        return Err(format!(
            "{} blocked: map-frame draw {} count must be nonzero",
            spec.renderer_label, draw.draw_index
        )
        .into());
    }
    if draw.topology.is_none() {
        return Err(format!(
            "{} blocked: map-frame draw {} has no captured IA primitive topology",
            spec.renderer_label, draw.draw_index
        )
        .into());
    }
    validate_map_frame_draw_args(draw, spec.renderer_label)?;
    if spec.terrain_strict {
        validate_map_frame_shader_identity(&draw.shader, frame, bundle_dir)?;
    } else {
        validate_generic_map_frame_shader_identity(&draw.shader, frame, bundle_dir, spec)?;
    }
    let vertex_shader = draw.vertex_shader.as_ref().ok_or_else(|| {
        format!(
            "{} blocked: map-frame draw {} has no active vertex shader bytecode/reflection evidence",
            spec.renderer_label, draw.draw_index
        )
    })?;
    if spec.terrain_strict {
        validate_map_frame_vertex_shader_identity(vertex_shader, frame, bundle_dir)?;
    } else {
        validate_generic_map_frame_vertex_shader_identity(vertex_shader, frame, bundle_dir, spec)?;
    }
    validate_map_frame_input_layout(&draw.input_layout, draw, spec.renderer_label)?;
    Ok(())
}

fn validate_map_frame_draw_args(draw: &MapFrameDraw, renderer_label: &str) -> Result<()> {
    match draw.draw_call.as_str() {
        "Draw" | "DrawIndexed" => {
            if draw.per_instance_count.is_some()
                || draw.instance_count.is_some()
                || draw.start_instance_location.is_some()
            {
                return Err(format!(
                    "{renderer_label} blocked: non-instanced map-frame draw {} must not carry instanced draw args",
                    draw.draw_index
                )
                .into());
            }
        }
        "DrawInstanced" | "DrawIndexedInstanced" => {
            let Some(per_instance_count) = draw.per_instance_count else {
                return Err(format!(
                    "{renderer_label} blocked: map-frame draw {} {} is missing per-instance count",
                    draw.draw_index, draw.draw_call
                )
                .into());
            };
            let Some(instance_count) = draw.instance_count else {
                return Err(format!(
                    "{renderer_label} blocked: map-frame draw {} {} is missing instance count",
                    draw.draw_index, draw.draw_call
                )
                .into());
            };
            if draw.start_instance_location.is_none() {
                return Err(format!(
                    "{renderer_label} blocked: map-frame draw {} {} is missing start instance location",
                    draw.draw_index, draw.draw_call
                )
                .into());
            }
            if per_instance_count == 0 || instance_count == 0 {
                return Err(format!(
                    "{renderer_label} blocked: map-frame draw {} {} has zero per-instance or instance count",
                    draw.draw_index, draw.draw_call
                )
                .into());
            }
            if per_instance_count.saturating_mul(instance_count) != draw.draw_count {
                return Err(format!(
                    "{renderer_label} blocked: map-frame draw {} {} count {} does not match per-instance count {} * instance count {}",
                    draw.draw_index,
                    draw.draw_call,
                    draw.draw_count,
                    per_instance_count,
                    instance_count
                )
                .into());
            }
        }
        _ => {}
    }
    Ok(())
}

fn validate_map_frame_shader_identity(
    shader: &MapFrameShader,
    frame: &MapFrameRuntimeBundle,
    bundle_dir: &Path,
) -> Result<()> {
    if shader.stage != "PS" {
        return Err(format!(
            "production terrain renderer blocked: active pdxmap shader stage {} is not PS",
            shader.stage
        )
        .into());
    }
    if shader.pointer.trim().is_empty() || shader.byte_len == 0 || shader.fnv1a64.trim().is_empty()
    {
        return Err(
            "production terrain renderer blocked: active pdxmap shader identity must include pointer, byte length, and hash"
                .into(),
        );
    }
    if shader.bytecode_file.trim().is_empty() {
        return Err(
            "production terrain renderer blocked: active pdxmap shader identity has no bytecode file"
                .into(),
        );
    }
    let evidence = frame
        .runtime_files
        .get(&shader.bytecode_file)
        .ok_or_else(|| {
            format!(
                "production terrain renderer blocked: active pdxmap shader bytecode {} is missing from runtime file evidence",
                shader.bytecode_file
            )
        })?;
    if evidence.byte_len != shader.byte_len || evidence.fnv1a64 != shader.fnv1a64 {
        return Err(format!(
            "production terrain renderer blocked: active pdxmap shader bytecode evidence {} does not match shader identity",
            shader.bytecode_file
        )
        .into());
    }
    validate_map_frame_file_evidence(bundle_dir, evidence)?;
    if !shader
        .reflection_resources
        .contains_key(TERRAIN_ID_RESOURCE_SYMBOL)
    {
        return Err(format!(
            "production terrain renderer blocked: active shader reflection does not declare {TERRAIN_ID_RESOURCE_SYMBOL}"
        )
        .into());
    }
    if !shader
        .source_evidence
        .iter()
        .any(|source| source == "gfx/FX/pdxmap.shader")
    {
        return Err(
            "production terrain renderer blocked: map-frame shader identity must cite gfx/FX/pdxmap.shader"
                .into(),
        );
    }
    Ok(())
}

fn validate_generic_map_frame_shader_identity(
    shader: &MapFrameShader,
    frame: &MapFrameRuntimeBundle,
    bundle_dir: &Path,
    spec: MapFrameBundleValidationSpec,
) -> Result<()> {
    if shader.stage != "PS" {
        return Err(format!(
            "{} blocked: active {} shader stage {} is not PS",
            spec.renderer_label, spec.capture_moment, shader.stage
        )
        .into());
    }
    validate_map_frame_shader_bytecode_evidence(
        shader,
        frame,
        bundle_dir,
        "pixel shader",
        spec.renderer_label,
        spec.capture_moment,
    )?;
    if shader.reflection_resources.is_empty() {
        return Err(format!(
            "{} blocked: active {} pixel shader reflection captured no texture resources",
            spec.renderer_label, spec.capture_moment
        )
        .into());
    }
    for resource in spec.required_reflected_resources {
        if !shader.reflection_resources.contains_key(*resource) {
            return Err(format!(
                "{} blocked: active {} pixel shader reflection does not declare required the game resource {}",
                spec.renderer_label, spec.capture_moment, resource
            )
            .into());
        }
    }
    if !shader
        .source_evidence
        .iter()
        .any(|source| source == spec.primary_shader_source)
    {
        return Err(format!(
            "{} blocked: active {} pixel shader identity must cite {}",
            spec.renderer_label, spec.capture_moment, spec.primary_shader_source
        )
        .into());
    }
    Ok(())
}

fn validate_map_frame_vertex_shader_identity(
    shader: &MapFrameShader,
    frame: &MapFrameRuntimeBundle,
    bundle_dir: &Path,
) -> Result<()> {
    if shader.stage != "VS" {
        return Err(format!(
            "production terrain renderer blocked: active terrain vertex shader stage {} is not VS",
            shader.stage
        )
        .into());
    }
    validate_map_frame_shader_bytecode_evidence(
        shader,
        frame,
        bundle_dir,
        "vertex shader",
        "production terrain renderer",
        "pdxmap",
    )?;
    let has_position = shader.input_parameters.iter().any(|parameter| {
        parameter.semantic_name.eq_ignore_ascii_case("POSITION")
            && parameter.semantic_index == 0
            && parameter.component_type == D3D_REGISTER_COMPONENT_SINT32
            && parameter.mask == 0x0f
    });
    let has_height = shader.input_parameters.iter().any(|parameter| {
        parameter.semantic_name.eq_ignore_ascii_case("TEXCOORD")
            && parameter.semantic_index == 0
            && parameter.component_type == D3D_REGISTER_COMPONENT_SINT32
            && parameter.mask & 0x03 == 0x03
    });
    if !has_position || !has_height {
        return Err(
            "production terrain renderer blocked: active terrain vertex shader reflection must include POSITION0 int4 and TEXCOORD0 height inputs"
                .into(),
        );
    }
    if shader
        .constant_buffers
        .get(TERRAIN_DRAW_CB1_LAYOUT_SOURCE)
        .copied()
        != Some(TERRAIN_DRAW_CB1_BIND_POINT)
    {
        return Err(format!(
            "production terrain renderer blocked: active terrain vertex shader reflection must bind {} at VS constant-buffer slot {}",
            TERRAIN_DRAW_CB1_LAYOUT_SOURCE, TERRAIN_DRAW_CB1_BIND_POINT
        )
        .into());
    }
    if !shader
        .source_evidence
        .iter()
        .any(|source| source == "gfx/FX/pdxmap.shader")
        || !shader
            .source_evidence
            .iter()
            .any(|source| source == "gfx/FX/pdxmap.fxh")
    {
        return Err(
            "production terrain renderer blocked: active terrain vertex shader identity must cite gfx/FX/pdxmap.shader and gfx/FX/pdxmap.fxh"
                .into(),
        );
    }
    Ok(())
}

fn validate_generic_map_frame_vertex_shader_identity(
    shader: &MapFrameShader,
    frame: &MapFrameRuntimeBundle,
    bundle_dir: &Path,
    spec: MapFrameBundleValidationSpec,
) -> Result<()> {
    if shader.stage != "VS" {
        return Err(format!(
            "{} blocked: active {} vertex shader stage {} is not VS",
            spec.renderer_label, spec.capture_moment, shader.stage
        )
        .into());
    }
    validate_map_frame_shader_bytecode_evidence(
        shader,
        frame,
        bundle_dir,
        "vertex shader",
        spec.renderer_label,
        spec.capture_moment,
    )?;
    if shader.input_parameters.is_empty() {
        return Err(format!(
            "{} blocked: active {} vertex shader reflection captured no input parameters",
            spec.renderer_label, spec.capture_moment
        )
        .into());
    }
    if !shader
        .source_evidence
        .iter()
        .any(|source| source == spec.primary_shader_source)
    {
        return Err(format!(
            "{} blocked: active {} vertex shader identity must cite {}",
            spec.renderer_label, spec.capture_moment, spec.primary_shader_source
        )
        .into());
    }
    Ok(())
}

fn validate_map_frame_shader_bytecode_evidence(
    shader: &MapFrameShader,
    frame: &MapFrameRuntimeBundle,
    bundle_dir: &Path,
    role: &str,
    renderer_label: &str,
    shader_label: &str,
) -> Result<()> {
    if shader.pointer.trim().is_empty() || shader.byte_len == 0 || shader.fnv1a64.trim().is_empty()
    {
        return Err(format!(
            "{renderer_label} blocked: active {shader_label} {role} identity must include pointer, byte length, and hash"
        )
        .into());
    }
    if shader.bytecode_file.trim().is_empty() {
        return Err(format!(
            "{renderer_label} blocked: active {shader_label} {role} identity has no bytecode file"
        )
        .into());
    }
    let evidence = frame
        .runtime_files
        .get(&shader.bytecode_file)
        .ok_or_else(|| {
            format!(
                "{renderer_label} blocked: active {shader_label} {role} bytecode {} is missing from runtime file evidence",
                shader.bytecode_file
            )
        })?;
    if evidence.byte_len != shader.byte_len || evidence.fnv1a64 != shader.fnv1a64 {
        return Err(format!(
            "{renderer_label} blocked: active {shader_label} {role} bytecode evidence {} does not match shader identity",
            shader.bytecode_file
        )
        .into());
    }
    validate_map_frame_file_evidence(bundle_dir, evidence)
}

fn validate_map_frame_vanilla_sources(
    frame: &MapFrameRuntimeBundle,
    bundle_dir: &Path,
    spec: MapFrameBundleValidationSpec,
) -> Result<()> {
    for &source in spec.required_vanilla_sources {
        let evidence = frame.vanilla_sources.get(source).ok_or_else(|| {
            format!(
                "{} blocked: map-frame bundle is missing vanilla source evidence for {source}",
                spec.renderer_label
            )
        })?;
        validate_map_frame_file_evidence(bundle_dir, evidence)?;
    }
    Ok(())
}

fn validate_map_frame_base_terrain_shipped_resources(
    frame: &MapFrameRuntimeBundle,
    bundle: &Path,
    manifest: &Manifest,
    contract: &MapMaterialContract,
) -> Result<()> {
    let mut blockers = Vec::new();
    for draw in &frame.draws {
        for (name, source) in TERRAIN_BASE_SHIPPED_SHADER_RESOURCES {
            validate_map_frame_post_diffuse_shipped_resource(
                draw,
                bundle,
                manifest,
                contract,
                name,
                source,
                &mut blockers,
            );
        }
    }
    if blockers.is_empty() {
        return Ok(());
    }
    Err(format!(
        "production terrain renderer blocked: base pdxmap terrain shader inputs are incomplete: {}",
        blockers.join("; ")
    )
    .into())
}

fn validate_map_frame_post_diffuse_inputs(
    frame: &MapFrameRuntimeBundle,
    bundle: &Path,
    map_frame_bundle_dir: &Path,
) -> Result<()> {
    let blockers = map_frame_post_diffuse_input_blockers(frame, bundle, map_frame_bundle_dir);
    if blockers.is_empty() {
        return Ok(());
    }
    Err(format!(
        "production terrain renderer blocked: post-diffuse pdxmap terrain shader inputs are incomplete: {}",
        blockers.join("; ")
    )
    .into())
}

fn map_frame_post_diffuse_input_blockers(
    frame: &MapFrameRuntimeBundle,
    bundle: &Path,
    map_frame_bundle_dir: &Path,
) -> Vec<String> {
    let mut blockers = Vec::new();
    for source in MAP_FRAME_REQUIRED_VANILLA_SOURCES {
        if !frame.vanilla_sources.contains_key(source) {
            blockers.push(format!("missing vanilla source evidence {source}"));
        }
    }

    let bundle_context = match load_post_diffuse_bundle_context(bundle) {
        Ok(context) => Some(context),
        Err(error) => {
            blockers.push(error.to_string());
            None
        }
    };

    for draw in &frame.draws {
        if let Some((manifest, contract)) = bundle_context.as_ref() {
            for (name, source) in TERRAIN_POST_DIFFUSE_SHIPPED_SHADER_RESOURCES {
                validate_map_frame_post_diffuse_shipped_resource(
                    draw,
                    bundle,
                    manifest,
                    contract,
                    name,
                    source,
                    &mut blockers,
                );
            }
        }
        for name in TERRAIN_POST_DIFFUSE_RUNTIME_SHADER_RESOURCES {
            validate_map_frame_post_diffuse_runtime_resource(
                frame,
                draw,
                bundle_context.as_ref().map(|(_, contract)| contract),
                name,
                &mut blockers,
            );
        }
        validate_map_frame_post_diffuse_vertex_outputs(
            frame,
            draw,
            bundle,
            map_frame_bundle_dir,
            &mut blockers,
        );
        for blocker in map_frame_post_diffuse_state_blockers(draw) {
            blockers.push(format!("draw {}: {blocker}", draw.draw_index));
        }
    }
    blockers
}

fn validate_map_frame_post_diffuse_vertex_outputs(
    frame: &MapFrameRuntimeBundle,
    draw: &MapFrameDraw,
    bundle: &Path,
    map_frame_bundle_dir: &Path,
    blockers: &mut Vec<String>,
) {
    let constants = match load_map_frame_terrain_shader_constants(frame, bundle) {
        Ok(constants) => constants,
        Err(error) => {
            blockers.push(error.to_string());
            return;
        }
    };
    match decode_map_frame_terrain_draw_outputs(draw, map_frame_bundle_dir, constants) {
        Ok((outputs, _)) => {
            if outputs.iter().any(|output| {
                [
                    output.v_screen_coord.x,
                    output.v_screen_coord.y,
                    output.v_screen_coord.z,
                    output.v_screen_coord.w,
                    output.v_shadow_proj.x,
                    output.v_shadow_proj.y,
                    output.v_shadow_proj.z,
                    output.v_shadow_proj.w,
                ]
                .iter()
                .any(|value| !value.is_finite())
            }) {
                blockers.push(
                    "VS_OUTPUT_TERRAIN.vScreenCoord/vShadowProj replay produced non-finite values"
                        .to_string(),
                );
            }
        }
        Err(error) => blockers.push(format!(
            "draw {} VS_OUTPUT_TERRAIN.vScreenCoord/vShadowProj replay blocked: {error}",
            draw.draw_index
        )),
    }
}

fn map_frame_post_diffuse_state_blockers(draw: &MapFrameDraw) -> Vec<String> {
    let mut blockers = Vec::new();
    let Some(state) = draw.draw_state.as_ref() else {
        return vec![
            "map-frame draw state has no viewport, scissor, rasterizer, depth-stencil, or blend state capture".to_string(),
        ];
    };
    if state.viewports.is_empty() {
        blockers.push("map-frame draw state has no captured viewport".to_string());
    }
    for (index, viewport) in state.viewports.iter().enumerate() {
        if !viewport.top_left_x.is_finite()
            || !viewport.top_left_y.is_finite()
            || !viewport.width.is_finite()
            || !viewport.height.is_finite()
            || !viewport.min_depth.is_finite()
            || !viewport.max_depth.is_finite()
            || viewport.width <= 0.0
            || viewport.height <= 0.0
            || viewport.min_depth > viewport.max_depth
        {
            blockers.push(format!(
                "map-frame draw state viewport {index} is not a valid D3D11 viewport"
            ));
        }
    }
    if !state.rasterizer.default_state && state.rasterizer.desc.is_none() {
        blockers.push("map-frame draw state has no rasterizer descriptor".to_string());
    }
    if !state.blend.default_state && state.blend.desc.is_none() {
        blockers.push("map-frame draw state has no blend descriptor".to_string());
    }
    if !state.depth_stencil.default_state && state.depth_stencil.desc.is_none() {
        blockers.push("map-frame draw state has no depth-stencil descriptor".to_string());
    }
    validate_map_frame_output_merger_state(state, &mut blockers);
    blockers
}

fn validate_map_frame_output_merger_state(state: &MapFrameDrawState, blockers: &mut Vec<String>) {
    let depth_enabled = state
        .depth_stencil
        .desc
        .as_ref()
        .map(|desc| desc.depth_enable)
        .unwrap_or(false);
    if !depth_enabled {
        return;
    }
    let Some(output_merger) = state.output_merger.as_ref() else {
        blockers.push(
            "depth test is enabled, but map-frame bundle has no output-merger target/depth resource evidence"
                .to_string(),
        );
        return;
    };
    if output_merger.render_targets.is_empty() {
        blockers.push(
            "depth test is enabled, but output-merger capture has no render target descriptor"
                .to_string(),
        );
    }
    for target in &output_merger.render_targets {
        validate_output_merger_texture(target, D3D11_BIND_RENDER_TARGET, "render target", blockers);
        validate_render_target_clear(target, blockers);
    }
    let Some(depth_stencil) = output_merger.depth_stencil.as_ref() else {
        blockers.push(
            "depth test is enabled, but output-merger capture has no depth-stencil descriptor"
                .to_string(),
        );
        return;
    };
    validate_output_merger_texture(
        depth_stencil,
        D3D11_BIND_DEPTH_STENCIL,
        "depth-stencil",
        blockers,
    );
    validate_depth_stencil_clear(
        depth_stencil,
        state
            .depth_stencil
            .desc
            .as_ref()
            .map(|desc| desc.stencil_enable)
            .unwrap_or(false),
        blockers,
    );
}

fn validate_output_merger_texture(
    texture: &MapFrameOutputMergerTexture,
    required_bind: u32,
    role: &str,
    blockers: &mut Vec<String>,
) {
    if texture.view_pointer.trim().is_empty() || texture.resource_pointer.trim().is_empty() {
        blockers.push(format!(
            "output-merger {role} descriptor is missing view/resource identity"
        ));
    }
    if texture.desc.width == 0 || texture.desc.height == 0 {
        blockers.push(format!(
            "output-merger {role} descriptor has zero dimensions"
        ));
    }
    if texture.desc.sample_count == 0 {
        blockers.push(format!(
            "output-merger {role} descriptor has zero sample count"
        ));
    }
    if texture.desc.bind_flags & required_bind == 0 {
        blockers.push(format!(
            "output-merger {role} descriptor bind flags {} do not include required D3D11 bind flag {required_bind}",
            texture.desc.bind_flags
        ));
    }
    if texture.view_desc.is_none() {
        blockers.push(format!(
            "output-merger {role} descriptor is missing captured D3D11 view descriptor"
        ));
    }
}

fn validate_render_target_clear(texture: &MapFrameOutputMergerTexture, blockers: &mut Vec<String>) {
    let Some(clear) = texture.last_render_target_clear.as_ref() else {
        blockers.push(
            "depth test is enabled, but output-merger render target has no captured ClearRenderTargetView provenance"
                .to_string(),
        );
        return;
    };
    if clear.sequence == 0 {
        blockers.push(
            "output-merger render target clear provenance has an invalid zero sequence".to_string(),
        );
    }
    if clear.color.iter().any(|channel| !channel.is_finite()) {
        blockers.push(
            "output-merger render target clear provenance contains a non-finite color".to_string(),
        );
    }
}

fn validate_depth_stencil_clear(
    texture: &MapFrameOutputMergerTexture,
    stencil_enabled: bool,
    blockers: &mut Vec<String>,
) {
    let Some(clear) = texture.last_depth_stencil_clear.as_ref() else {
        blockers.push(
            "depth test is enabled, but output-merger depth-stencil has no captured ClearDepthStencilView provenance"
                .to_string(),
        );
        return;
    };
    if clear.sequence == 0 {
        blockers.push(
            "output-merger depth-stencil clear provenance has an invalid zero sequence".to_string(),
        );
    }
    if clear.clear_flags & D3D11_CLEAR_DEPTH == 0 {
        blockers.push(
            "output-merger depth-stencil clear provenance did not clear D3D11 depth".to_string(),
        );
    }
    if stencil_enabled && clear.clear_flags & D3D11_CLEAR_STENCIL == 0 {
        blockers.push(
            "output-merger depth-stencil clear provenance did not clear D3D11 stencil while stencil test is enabled"
                .to_string(),
        );
    }
    if !clear.depth.is_finite() || !(0.0..=1.0).contains(&clear.depth) {
        blockers.push(
            "output-merger depth-stencil clear provenance has a depth outside D3D11 0..1"
                .to_string(),
        );
    }
}

fn load_post_diffuse_bundle_context(bundle: &Path) -> Result<(Manifest, MapMaterialContract)> {
    let manifest: Manifest = serde_json::from_slice(&fs::read(bundle.join("manifest.json"))?)?;
    if manifest.schema != "battle-plan-rust-map-bundle-v1" {
        return Err(format!("unsupported map bundle schema: {}", manifest.schema).into());
    }
    let contract: MapMaterialContract = serde_json::from_slice(&fs::read(
        bundle.join(&manifest.files.map_material_contract),
    )?)?;
    validate_material_mip_outputs(&contract, bundle)?;
    Ok((manifest, contract))
}

fn validate_map_frame_post_diffuse_shipped_resource(
    draw: &MapFrameDraw,
    bundle: &Path,
    manifest: &Manifest,
    contract: &MapMaterialContract,
    name: &str,
    source: &str,
    blockers: &mut Vec<String>,
) {
    let Some(resource) = map_frame_post_diffuse_bound_resource(draw, name, blockers) else {
        return;
    };
    let Ok(meta) = material_source_meta(contract, source) else {
        blockers.push(format!(
            "shader resource {name} is a shipped material sampler, but material contract has no source metadata for {source}"
        ));
        return;
    };
    if !meta
        .shader_samplers
        .iter()
        .any(|sampler| sampler.as_str() == name)
    {
        blockers.push(format!(
            "shader resource {name} is not listed as a sampler consumer of shipped material {source}"
        ));
    }
    if resource.width != meta.dimensions.width as u32
        || resource.height != meta.dimensions.height as u32
    {
        blockers.push(format!(
            "shader resource {name} SRV is {}x{}, but shipped material {source} is {}x{}",
            resource.width, resource.height, meta.dimensions.width, meta.dimensions.height
        ));
    }
    if resource.mip_count != meta.mip_count {
        blockers.push(format!(
            "shader resource {name} SRV has {} mip(s), but shipped material {source} has {}",
            resource.mip_count, meta.mip_count
        ));
    }
    if let Err(error) = shipped_material_color_space(name, resource) {
        blockers.push(error.to_string());
    }
    if let Err(error) = required_shader_source_path(bundle, manifest, source) {
        blockers.push(error.to_string());
    }
    if meta.mip_count > 1 && meta.mip_output.is_none() {
        blockers.push(format!(
            "shader resource {name} uses mipped shipped material {source}, but the material contract has no exact mip-chain output"
        ));
    }
    let sampler = draw
        .samplers
        .iter()
        .find(|sampler| sampler.stage == "PS" && sampler.slot == resource.slot);
    match sampler {
        Some(sampler) => {
            if let Err(error) = validate_map_frame_linear_wrap_sampler(name, sampler) {
                blockers.push(error.to_string());
            }
        }
        None => blockers.push(format!(
            "shader resource {name} at PS slot {} has no sampler-state proof",
            resource.slot
        )),
    }
}

fn validate_map_frame_post_diffuse_runtime_resource(
    frame: &MapFrameRuntimeBundle,
    draw: &MapFrameDraw,
    contract: Option<&MapMaterialContract>,
    name: &str,
    blockers: &mut Vec<String>,
) {
    let Some(resource) = map_frame_post_diffuse_bound_resource(draw, name, blockers) else {
        return;
    };
    if resource.is_null {
        if name == SHADOW_MAP_SYMBOL {
            if let Err(error) = validate_map_frame_null_shadow_resource(draw, resource) {
                blockers.push(error.to_string());
            }
        } else {
            blockers.push(format!(
                "shader resource {name} at PS slot {} is explicitly null in captured D3D11 state",
                resource.slot
            ));
        }
        return;
    }
    if resource.file.is_none() || resource.fnv1a64.is_none() || resource.byte_len == 0 {
        let provenance = contract
            .and_then(|contract| runtime_input_reason_for_symbol(contract, name))
            .map(|reason| format!(" ({reason})"))
            .unwrap_or_default();
        blockers.push(format!(
            "shader resource {name} at PS slot {} is generated/runtime and has no captured bytes/hash{provenance}",
            resource.slot
        ));
        return;
    }
    if let Err(error) = validate_map_frame_runtime_resource(name, resource) {
        blockers.push(error.to_string());
        return;
    }
    let sampler = draw
        .samplers
        .iter()
        .find(|sampler| sampler.stage == "PS" && sampler.slot == resource.slot);
    match sampler {
        Some(sampler) => {
            let sampler_validation = match name {
                LIGHT_INDEX_MAP_SYMBOL | LIGHT_DATA_MAP_SYMBOL => {
                    validate_map_frame_point_clamp_sampler(name, sampler)
                }
                PROVINCE_SECONDARY_COLOR_MAP_SYMBOL | SNOW_MUD_DATA_SYMBOL => {
                    validate_map_frame_linear_wrap_sampler(name, sampler)
                }
                GRADIENT_BORDER_CHANNEL1_SYMBOL | GRADIENT_BORDER_CHANNEL2_SYMBOL => {
                    validate_map_frame_linear_clamp_sampler(name, sampler)
                }
                _ => Ok(()),
            };
            if let Err(error) = sampler_validation {
                blockers.push(error.to_string());
            }
        }
        None => blockers.push(format!(
            "shader resource {name} at PS slot {} has no sampler-state proof",
            resource.slot
        )),
    }
    if let Err(error) = validate_map_frame_runtime_file_link(frame, resource, name) {
        blockers.push(error.to_string());
    }
}

fn validate_map_frame_null_shadow_resource(
    draw: &MapFrameDraw,
    resource: &MapFrameTextureBinding,
) -> Result<()> {
    if resource.declared_name.as_deref() != Some(SHADOW_MAP_SYMBOL) {
        return Err(format!(
            "production terrain renderer blocked: null shadow SRV slot {} is declared as {:?}, expected {SHADOW_MAP_SYMBOL}",
            resource.slot, resource.declared_name
        )
        .into());
    }
    if resource.file.is_some()
        || resource.fnv1a64.is_some()
        || resource.byte_len != 0
        || resource.dxgi_format != 0
        || resource.width != 0
        || resource.height != 0
        || resource.mip_count != 0
        || resource.bind_flags != 0
        || resource.usage != 0
    {
        return Err(format!(
            "production terrain renderer blocked: null {SHADOW_MAP_SYMBOL} SRV at PS slot {} must not carry fake texture metadata or bytes",
            resource.slot
        )
        .into());
    }
    let sampler = draw
        .samplers
        .iter()
        .find(|sampler| sampler.stage == "PS" && sampler.slot == resource.slot)
        .ok_or_else(|| {
            format!(
                "production terrain renderer blocked: null {SHADOW_MAP_SYMBOL} PS slot {} has no sampler-state proof",
                resource.slot
            )
        })?;
    validate_map_frame_linear_wrap_sampler(SHADOW_MAP_SYMBOL, sampler)
}

fn map_frame_post_diffuse_bound_resource<'a>(
    draw: &'a MapFrameDraw,
    name: &str,
    blockers: &mut Vec<String>,
) -> Option<&'a MapFrameTextureBinding> {
    let Some(slot) = draw.shader.reflection_resources.get(name) else {
        blockers.push(format!(
            "draw {} shader reflection/capture does not identify required pdxmap resource {name}",
            draw.draw_index
        ));
        return None;
    };
    let resource = draw
        .shader_resources
        .iter()
        .find(|resource| resource.stage == "PS" && resource.slot == *slot);
    let Some(resource) = resource else {
        blockers.push(format!(
            "shader resource {name} is declared at PS slot {slot}, but no SRV binding was captured"
        ));
        return None;
    };
    if resource.declared_name.as_deref() != Some(name) {
        blockers.push(format!(
            "shader resource {name} is expected at PS slot {slot}, but the bound SRV declared name is {:?}",
            resource.declared_name
        ));
    }
    Some(resource)
}

fn runtime_input_reason_for_symbol<'a>(
    contract: &'a MapMaterialContract,
    symbol: &str,
) -> Option<&'a str> {
    contract
        .generated_runtime_inputs
        .values()
        .find(|input| {
            input
                .shader_symbols
                .iter()
                .any(|candidate| candidate == symbol)
        })
        .map(|input| input.reason.as_str())
}

fn validate_map_frame_input_layout(
    input_layout: &MapFrameInputLayout,
    draw: &MapFrameDraw,
    renderer_label: &str,
) -> Result<()> {
    if input_layout.pointer.trim().is_empty() || input_layout.elements.is_empty() {
        return Err(format!(
            "{renderer_label} blocked: map-frame input layout must include pointer and elements"
        )
        .into());
    }
    for element in &input_layout.elements {
        let key = element.input_slot.to_string();
        let vertex_buffer = draw.vertex_buffers.get(&key).ok_or_else(|| {
            format!(
                "{renderer_label} blocked: map-frame input layout {}{} uses IA slot {}, but the bundle has no vertex buffer for that slot",
                element.semantic_name, element.semantic_index, element.input_slot
            )
        })?;
        if vertex_buffer.stage != "IA" {
            return Err(format!(
                "{renderer_label} blocked: vertex buffer slot {} stage {} is not IA",
                element.input_slot, vertex_buffer.stage
            )
            .into());
        }
        let stride = vertex_buffer.stride.ok_or_else(|| {
            format!(
                "{renderer_label} blocked: vertex buffer slot {} is missing stride",
                element.input_slot
            )
        })?;
        if stride == 0 {
            return Err(format!(
                "{renderer_label} blocked: vertex buffer slot {} has zero stride",
                element.input_slot
            )
            .into());
        }
        let format_byte_width = d3d11_input_format_byte_width(element.format).ok_or_else(|| {
            format!(
                "{renderer_label} blocked: input layout {}{} has unsupported DXGI format {}",
                element.semantic_name, element.semantic_index, element.format
            )
        })?;
        if element.aligned_byte_offset == D3D11_APPEND_ALIGNED_ELEMENT {
            return Err(format!(
                "{renderer_label} blocked: input layout {}{} uses D3D11_APPEND_ALIGNED_ELEMENT",
                element.semantic_name, element.semantic_index
            )
            .into());
        }
        if element
            .aligned_byte_offset
            .saturating_add(format_byte_width)
            > stride
        {
            return Err(format!(
                "{renderer_label} blocked: input layout {}{} offset {} plus {} bytes exceeds slot {} stride {}",
                element.semantic_name,
                element.semantic_index,
                element.aligned_byte_offset,
                format_byte_width,
                element.input_slot,
                stride
            )
            .into());
        }
    }
    Ok(())
}

fn validate_map_frame_resources(
    frame: &MapFrameRuntimeBundle,
    bundle_dir: &Path,
    spec: MapFrameBundleValidationSpec,
) -> Result<()> {
    for evidence in frame.runtime_files.values() {
        validate_map_frame_file_evidence(bundle_dir, evidence)?;
    }
    for draw in &frame.draws {
        if spec.terrain_strict {
            validate_map_frame_draw_resources(draw, frame, bundle_dir)?;
        } else {
            validate_generic_map_frame_draw_resources(draw, frame, bundle_dir, spec)?;
        }
    }
    Ok(())
}

fn validate_generic_map_frame_draw_resources(
    draw: &MapFrameDraw,
    frame: &MapFrameRuntimeBundle,
    bundle_dir: &Path,
    spec: MapFrameBundleValidationSpec,
) -> Result<()> {
    if draw.vertex_buffers.is_empty() {
        return Err(format!(
            "{} blocked: map-frame draw {} has no IA vertex-buffer captures",
            spec.renderer_label, draw.draw_index
        )
        .into());
    }
    for vertex_buffer in draw.vertex_buffers.values() {
        validate_map_frame_buffer_file(bundle_dir, vertex_buffer, "vertex buffer")?;
    }
    if draw.constant_buffers.is_empty() {
        return Err(format!(
            "{} blocked: map-frame draw {} has no VS/PS constant-buffer captures",
            spec.renderer_label, draw.draw_index
        )
        .into());
    }
    for constant_buffer in &draw.constant_buffers {
        validate_map_frame_constant_buffer(bundle_dir, constant_buffer)?;
    }
    validate_map_frame_reflected_constant_buffer_bindings(&draw.shader, draw, spec.renderer_label)?;
    if let Some(vertex_shader) = draw.vertex_shader.as_ref() {
        validate_map_frame_reflected_constant_buffer_bindings(
            vertex_shader,
            draw,
            spec.renderer_label,
        )?;
    }
    if spec.capture_moment == WATER_CAPTURE_MOMENT {
        validate_map_frame_app_camera_constant_buffer_coverage(
            draw,
            bundle_dir,
            spec.renderer_label,
        )?;
    }
    if draw.draw_call.contains("Indexed") {
        let index_buffer = draw.index_buffer.as_ref().ok_or_else(|| {
            format!(
                "{} blocked: indexed map-frame draw {} has no index buffer binding",
                spec.renderer_label, draw.draw_index
            )
        })?;
        validate_map_frame_index_buffer(bundle_dir, index_buffer)?;
    }
    validate_map_frame_bound_resource_names(draw, spec.renderer_label)?;
    validate_map_frame_reflected_resource_bindings(draw, spec.renderer_label)?;
    validate_map_frame_reflected_sampler_bindings(draw, spec.renderer_label)?;
    if spec.capture_moment == WATER_CAPTURE_MOMENT {
        validate_pdxwater_sampler_contract(draw, frame, bundle_dir, spec.renderer_label)?;
    }
    for resource in &draw.shader_resources {
        validate_map_frame_texture_file(bundle_dir, resource)?;
    }
    if draw.samplers.is_empty() {
        return Err(format!(
            "{} blocked: map-frame draw {} has no PS sampler-state captures",
            spec.renderer_label, draw.draw_index
        )
        .into());
    }
    for resource in draw
        .shader_resources
        .iter()
        .filter(|resource| !resource.is_null)
    {
        if resource.bind_flags & D3D11_BIND_SHADER_RESOURCE == 0 {
            return Err(format!(
                "{} blocked: map-frame draw {} shader resource {:?} slot {} missing D3D11_BIND_SHADER_RESOURCE",
                spec.renderer_label, draw.draw_index, resource.declared_name, resource.slot
            )
            .into());
        }
        if resource.view_desc.is_none() {
            return Err(format!(
                "{} blocked: map-frame draw {} shader resource {:?} slot {} is missing captured SRV descriptor",
                spec.renderer_label, draw.draw_index, resource.declared_name, resource.slot
            )
            .into());
        }
        if spec.capture_moment == WATER_CAPTURE_MOMENT
            && resource.declared_name.as_deref() == Some(WATER_REFRACTION_RESOURCE_SYMBOL)
        {
            validate_app_owned_water_refraction_binding(
                draw.draw_index,
                resource,
                spec.renderer_label,
            )?;
            continue;
        }
        if resource.file.is_none() || resource.fnv1a64.is_none() || resource.byte_len == 0 {
            return Err(format!(
                "{} blocked: map-frame draw {} shader resource {:?} slot {} must include captured bytes and hash",
                spec.renderer_label, draw.draw_index, resource.declared_name, resource.slot
            )
            .into());
        }
    }
    for blocker in map_frame_post_diffuse_state_blockers(draw) {
        return Err(format!(
            "{} blocked: map-frame draw {}: {blocker}",
            spec.renderer_label, draw.draw_index
        )
        .into());
    }
    Ok(())
}

fn validate_app_owned_water_refraction_binding(
    draw_index: u32,
    resource: &MapFrameTextureBinding,
    renderer_label: &str,
) -> Result<()> {
    if resource.is_null {
        return Err(format!(
            "{renderer_label} blocked: map-frame draw {draw_index} {WATER_REFRACTION_RESOURCE_SYMBOL} cannot be null because the production graph binds the app-owned terrain color target there"
        )
        .into());
    }
    if resource.width == 0
        || resource.height == 0
        || resource.dxgi_format == 0
        || resource.mip_count == 0
        || resource.array_size == 0
        || resource.sample_count == 0
    {
        return Err(format!(
            "{renderer_label} blocked: map-frame draw {draw_index} {WATER_REFRACTION_RESOURCE_SYMBOL} needs captured D3D11 texture descriptor metadata even when raw bytes are supplied by the app-owned terrain color target"
        )
        .into());
    }
    let Some(view) = resource.view_desc.as_ref() else {
        return Err(format!(
            "{renderer_label} blocked: map-frame draw {draw_index} {WATER_REFRACTION_RESOURCE_SYMBOL} needs captured SRV descriptor evidence"
        )
        .into());
    };
    if view.view_dimension != D3D11_SRV_DIMENSION_TEXTURE2D {
        return Err(format!(
            "{renderer_label} blocked: map-frame draw {draw_index} {WATER_REFRACTION_RESOURCE_SYMBOL} must be a Texture2D SRV for the app-owned terrain color target"
        )
        .into());
    }
    Ok(())
}

fn validate_map_frame_draw_resources(
    draw: &MapFrameDraw,
    frame: &MapFrameRuntimeBundle,
    bundle_dir: &Path,
) -> Result<()> {
    for vertex_buffer in draw.vertex_buffers.values() {
        validate_map_frame_buffer_file(bundle_dir, vertex_buffer, "vertex buffer")?;
    }
    if draw.constant_buffers.is_empty() {
        return Err(format!(
            "production terrain renderer blocked: map-frame draw {} has no VS/PS constant-buffer captures",
            draw.draw_index
        )
        .into());
    }
    for constant_buffer in &draw.constant_buffers {
        validate_map_frame_constant_buffer(bundle_dir, constant_buffer)?;
    }
    if !draw.constant_buffers.iter().any(|buffer| {
        buffer.stage == "PS"
            && buffer.slot == TERRAIN_SCENE_CB0_BIND_POINT
            && buffer.declared_name.as_deref() == Some(TERRAIN_SCENE_CB0_SYMBOL)
    }) {
        return Err(format!(
            "production terrain renderer blocked: map-frame draw {} has no named {TERRAIN_SCENE_CB0_SYMBOL} PS constant-buffer capture at slot {TERRAIN_SCENE_CB0_BIND_POINT}",
            draw.draw_index
        )
        .into());
    }
    if draw.draw_call.contains("Indexed") {
        let index_buffer = draw.index_buffer.as_ref().ok_or(
            "production terrain renderer blocked: indexed map-frame draw has no index buffer binding",
        )?;
        validate_map_frame_index_buffer(bundle_dir, index_buffer)?;
    }
    let terrain_slot = draw.shader.reflection_resources[TERRAIN_ID_RESOURCE_SYMBOL];
    let terrain_srv = map_frame_shader_resource(draw, TERRAIN_ID_RESOURCE_SYMBOL)?;
    validate_map_frame_runtime_rgba_resource(TERRAIN_ID_RESOURCE_SYMBOL, terrain_srv)?;
    validate_map_frame_runtime_file_link(frame, terrain_srv, TERRAIN_ID_RESOURCE_SYMBOL)?;
    validate_map_frame_texture_file(bundle_dir, terrain_srv)?;
    let terrain_sampler = draw
        .samplers
        .iter()
        .find(|sampler| sampler.stage == "PS" && sampler.slot == terrain_slot)
        .ok_or_else(|| {
            format!(
                "production terrain renderer blocked: active TerrainIDMap PS slot {terrain_slot} has no sampler-state proof"
            )
        })?;
    validate_map_frame_terrain_sampler(terrain_sampler)?;
    if draw
        .shader
        .reflection_resources
        .contains_key(SNOW_MUD_DATA_SYMBOL)
    {
        let snow_mud_slot = draw.shader.reflection_resources[SNOW_MUD_DATA_SYMBOL];
        let resource = map_frame_shader_resource(draw, SNOW_MUD_DATA_SYMBOL)?;
        validate_map_frame_runtime_rgba_resource(SNOW_MUD_DATA_SYMBOL, resource)?;
        validate_map_frame_runtime_file_link(frame, resource, SNOW_MUD_DATA_SYMBOL)?;
        let sampler = draw
            .samplers
            .iter()
            .find(|sampler| sampler.stage == "PS" && sampler.slot == snow_mud_slot)
            .ok_or_else(|| {
                format!(
                    "production terrain renderer blocked: active {SNOW_MUD_DATA_SYMBOL} PS slot {snow_mud_slot} has no sampler-state proof"
                )
            })?;
        validate_map_frame_linear_wrap_sampler(SNOW_MUD_DATA_SYMBOL, sampler)?;
    }
    validate_map_frame_bound_resource_names(draw, "production terrain renderer")?;
    for resource in &draw.shader_resources {
        validate_map_frame_texture_file(bundle_dir, resource)?;
    }
    Ok(())
}

fn validate_map_frame_bound_resource_names(
    draw: &MapFrameDraw,
    renderer_label: &str,
) -> Result<()> {
    for resource in &draw.shader_resources {
        let Some(name) = resource.declared_name.as_ref() else {
            continue;
        };
        let expected_slot = draw.shader.reflection_resources.get(name).ok_or_else(|| {
            format!(
                "{renderer_label} blocked: PS slot {} is declared as {name}, but active shader reflection has no matching resource name",
                resource.slot
            )
        })?;
        if *expected_slot != resource.slot {
            return Err(format!(
                "{renderer_label} blocked: PS slot {} is declared as {name}, but active shader reflection expects slot {expected_slot}",
                resource.slot
            )
            .into());
        }
    }
    Ok(())
}

fn validate_map_frame_reflected_constant_buffer_bindings(
    shader: &MapFrameShader,
    draw: &MapFrameDraw,
    renderer_label: &str,
) -> Result<()> {
    if let Some(blocker) = map_frame_reflected_constant_buffer_binding_blockers(shader, draw)
        .into_iter()
        .next()
    {
        return Err(format!("{renderer_label} blocked: {blocker}").into());
    }
    Ok(())
}

fn map_frame_reflected_constant_buffer_binding_blockers(
    shader: &MapFrameShader,
    draw: &MapFrameDraw,
) -> Vec<String> {
    let mut blockers = Vec::new();
    for (name, slot) in &shader.constant_buffers {
        let Some(buffer) = draw
            .constant_buffers
            .iter()
            .find(|buffer| buffer.stage == shader.stage && buffer.slot == *slot)
        else {
            blockers.push(format!(
                "map-frame draw {} active {} shader reflects constant buffer {name} at slot {slot}, but the bundle has no captured {} constant-buffer binding for that slot",
                draw.draw_index, shader.stage, shader.stage
            ));
            continue;
        };
        if buffer.declared_name.as_deref() != Some(name.as_str()) {
            blockers.push(format!(
                "map-frame draw {} {} constant-buffer slot {slot} is captured as {:?}, expected reflected constant buffer {name}",
                draw.draw_index, shader.stage, buffer.declared_name
            ));
        }
    }
    blockers
}

fn validate_map_frame_app_camera_constant_buffer_coverage(
    draw: &MapFrameDraw,
    bundle_dir: &Path,
    renderer_label: &str,
) -> Result<()> {
    let mut found = false;
    for binding in draw
        .constant_buffers
        .iter()
        .filter(|binding| is_terrain_scene_cb0_camera_binding(binding))
    {
        if terrain_scene_cb0_camera_layout_for_binding(bundle_dir, draw, binding, binding.byte_len)?
            .is_some()
        {
            validate_camera_constant_buffer_update_binding(
                binding,
                binding.byte_len,
                draw.draw_index,
            )?;
            found = true;
        }
    }
    if !found {
        return Err(format!(
            "{renderer_label} blocked: map-frame draw {} has no camera-updatable {TERRAIN_SCENE_CB0_SYMBOL} constant buffer for the app-owned map camera",
            draw.draw_index
        )
        .into());
    }
    Ok(())
}

