    fn sync_active_shader_bindings_to_draws(frame: &mut MapFrameRuntimeBundle) {
        for draw in &mut frame.draws {
            draw.shader.reflection_resources =
                frame.active_draw.shader.reflection_resources.clone();
            draw.shader_resources = frame.active_draw.shader_resources.clone();
            draw.samplers = frame.active_draw.samplers.clone();
        }
    }

    fn add_map_frame_sampler(
        frame: &mut MapFrameRuntimeBundle,
        slot: u32,
        filter: u32,
        address_u: u32,
        address_v: u32,
    ) {
        frame.active_draw.samplers.push(MapFrameSamplerBinding {
            stage: "PS".to_string(),
            slot,
            filter,
            address_u,
            address_v,
            address_w: address_v,
            mip_lod_bias: 0.0,
            max_anisotropy: 1,
            comparison_func: 0,
            border_color: [0.0; 4],
            min_lod: 0.0,
            max_lod: f32::MAX,
        });
    }

    fn add_uncaptured_map_frame_resource(
        frame: &mut MapFrameRuntimeBundle,
        symbol: &str,
        slot: u32,
        width: u32,
        height: u32,
        mip_count: u32,
    ) {
        frame
            .active_draw
            .shader
            .reflection_resources
            .insert(symbol.to_string(), slot);
        frame
            .active_draw
            .shader_resources
            .push(MapFrameTextureBinding {
                stage: "PS".to_string(),
                slot,
                declared_name: Some(symbol.to_string()),
                is_null: false,
                view_desc: None,
                file: None,
                byte_len: 0,
                fnv1a64: None,
                dxgi_format: DXGI_FORMAT_R8G8B8A8_UNORM,
                width,
                height,
                mip_count,
                array_size: 1,
                sample_count: 1,
                sample_quality: 0,
                payload_format: None,
                subresources: Vec::new(),
                bind_flags: 8,
                usage: 0,
                cpu_access_flags: 0,
                misc_flags: 0,
            });
    }

